false},{"enonce":"Associe chaque ultrastructure à son rôle.","aide":"Pense à ce que chacun fabrique, digère ou délimite.","type":"association","gauche":[{"id":"g0","texte":"Ribosomes"},{"id":"g1","texte":"Réticulum lisse"},{"id":"g2","texte":"Lysosome"},{"id":"g3","texte":"Membrane plasmique"}],"droite":[{"id":"d0","texte":"Digestion intracellulaire"},{"id":"d1","texte":"Synthèse des protéines"},{"id":"d2","texte":"Synthèse des lipides"},{"id":"d3","texte":"Délimite la cellule et contrôle les échanges"}]}]}$ex$::jsonb,
