   $ex${"titre":"Le genou de Julie, l’articulation en coupe","competence":"observer-schema","situation":"Julie, handballeuse, souffre du genou. Son kinésithérapeute dessine l’articulation en coupe pour lui expliquer ce qui peut s’user, puis lui montre le vocabulaire du compte rendu.","documents":[{"id":"genou","type":"schema","titre":"Une articulation mobile, en coupe (schéma)","largeur":320,"hauteur":290,"elements":[{"forme":"rect","x":110,"y":15,"l":100,"h":100,"arrondi":10,"teinte":"sable","motif":"plein"},{"forme":"rect","x":110,"y":115,"l":100,"h":9,"teinte":"bleu","motif":"plein","id":"z1","zone":true},{"forme":"rect","x":110,"y":124,"l":100,"h":20,"teinte":"turquoise","motif":"clair","id":"z2","zone":true},{"forme":"rect","x":110,"y":144,"l":100,"h":9,"teinte":"bleu","motif":"plein"},{"forme":"rect","x":110,"y":153,"l":100,"h":110,"arrondi":10,"teinte":"sable","motif":"plein"},{"forme":"rect","x":98,"y":108,"l":8,"h":52,"teinte":"ambre","motif":"plein","id":"z3","zone":true},{"forme":"rect","x":214,"y":108,"l":8,"h":52,"teinte":"ambre","motif":"plein"},{"forme":"rect","x":232,"y":80,"l":8,"h":110,"arrondi":3,"teinte":"corail","motif":"plein","id":"z4","zone":true},{"forme":"texte","x":40,"y":60,"texte":"Os 1","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"texte","x":40,"y":215,"texte":"Os 2","taille":"petit","italique":true,"ancre":"milieu"}]},{"id":"racines","type":"tableau","titre":"Quelques racines médicales","colonnes":["Racine","Sens"],"lignes":[["arthr(o)","articulation"],["gon(o)","genou"],["cox(o)","hanche"],["chondr(o)","cartilage"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’espace rempli du liquide qui lubrifie l’articulation.","aide":"Il se trouve entre les deux extrémités osseuses recouvertes de cartilage.","type":"zone","document":"genou","multiple":false},{"enonce":"Touche l’élément qui relie les deux os entre eux et les stabilise.","aide":"Il passe à l’extérieur de la capsule et relie un os à l’autre.","type":"zone","document":"genou","multiple":false},{"enonce":"Associe chaque élément de l’articulation à son rôle.","aide":"Pense à l’ordre de l’intérieur vers l’extérieur : cartilage, liquide, membrane, capsule.","type":"association","gauche":[{"id":"g0","texte":"Cartilage articulaire"},{"id":"g1","texte":"Capsule articulaire"},{"id":"g2","texte":"Membrane synoviale"},{"id":"g3","texte":"Ligaments"}],"droite":[{"id":"d0","texte":"Sécrète le liquide synovial"},{"id":"d1","texte":"Relient les os entre eux"},{"id":"d2","texte":"Manchon fibreux qui enferme l’articulation"},{"id":"d3","texte":"Amortit et fait glisser"}]},{"enonce":"Le compte rendu de Julie mentionne une « gonarthrose ». Que signifie ce mot ?","aide":"Décompose le mot : gon(o) + arthr(o) + le suffixe qui désigne l’usure.","type":"choix","options":[{"id":"a","texte":"Une arthrose du genou"},{"id":"b","texte":"Une arthrose de la hanche"},{"id":"c","texte":"Une inflammation du tendon"},{"id":"d","texte":"Une fracture du cartilage"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le **liquide synovial**, sécrété par la membrane synoviale, remplit la cavité : il lubrifie et nourrit le cartilage."},{"cle":{"type":"zone","ids":["z4"]},"explication":"Un **ligament** relie les os entre eux et stabilise l’articulation. C’est un **tendon** qui relie un muscle à un os."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"Le **cartilage** amortit et fait glisser, la **capsule** enferme, la **membrane synoviale** sécrète le liquide, les **ligaments** relient les os."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Gon(o)** = genou, **arthr(o)** = articulation : la gonarthrose est l’**arthrose du genou**, c’est-à-dire l’usure de son cartilage."}]$ex$::jsonb),
  ('d1fc758f-3cef-5d26-ae3a-350321cc640b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quel examen d’imagerie pour quel patient ?","competence":"raisonner","situation":"Un service d’imagerie reçoit quatre demandes d’examen le même matin. Le médecin doit choisir la technique la plus adaptée à chaque patient en tenant compte de ses limites et de ses contre-indications.","documents":[{"id":"demandes","type":"tableau","titre":"Les demandes du matin","colonnes":["Patient","Situation"],"lignes":[["Karim, 22 ans","Chute à vélo, suspicion de fracture du poignet : examen simple et rapide"],["Julie, 27 ans","Handballeuse, genou qui lâche : lésion d’un ligament soupçonnée"],["Marc, 45 ans","Accident grave, fractures complexes du bassin : coupes sans superposition"],["Mme Roux, enceinte","Douleur à la cheville : on cherche à éviter tout rayonnement ionisant"],["M. Dupuis, 58 ans","Douleur au genou, éclats métalliques dans l’œil depuis un accident de travail"]],"enteteLignes":true,"source":"Patients fictifs"},{"id":"techniques","type":"tableau","titre":"Les trois techniques d’imagerie","colonnes":["Technique","Rayons X","Image obtenue","Précaution"],"lignes":[["Radiographie","oui, ionisants","plane : les structures se superposent","en principe contre-indiquée chez la femme enceinte"],["Scanner","oui, dose plus élevée","coupes fines, sans superposition","dose de rayons X à surveiller"],["IRM","non : champ magnétique","excellente pour les tissus mous","contre-indiquée avec certains objets métalliques"]],"enteteLignes":true}],"questions":[{"enonce":"Quelle technique conviendrait à chacun de ces patients ?","aide":"Un os cassé : radiographie. Des coupes fines pour un traumatisme complexe : scanner. Les tissus mous (ligaments) : IRM.","type":"categories","categories":[{"id":"c0","texte":"Radiographie"},{"id":"c1","texte":"Scanner"},{"id":"c2","texte":"IRM"}],"items":[{"id":"i0","texte":"Mme Roux"},{"id":"i1","texte":"Marc"},{"id":"i2","texte":"Julie"},{"id":"i3","texte":"Karim"}]},{"enonce":"Touche la case qui explique pourquoi on évite la radiographie chez Mme Roux.","aide":"Cherche dans la colonne « Précaution », ligne « Radiographie ».","type":"zone","document":"techniques","multiple":false},{"enonce":"M. Dupuis souffre du genou, mais il a des éclats métalliques dans l’œil. Quel examen faut-il écarter ?","aide":"Un champ magnétique intense attire certains métaux.","type":"choix","options":[{"id":"a","texte":"Aucun, tous sont possibles"},{"id":"b","texte":"La radiographie"},{"id":"c","texte":"L’IRM"},{"id":"d","texte":"Le scanner"}],"multiple":false},{"enonce":"Pourquoi l’IRM est-elle la meilleure technique pour le genou de Julie ?","aide":"Un ligament n’est pas un os : quelle technique voit ce que les rayons X voient mal ?","type":"choix","options":[{"id":"a","texte":"Elle ne coûte rien et elle est très rapide à passer"},{"id":"b","texte":"Elle montre bien les tissus mous, comme les ligaments"},{"id":"c","texte":"Elle montre seulement l’os, sans aucune autre structure"},{"id":"d","texte":"Elle utilise des rayons X plus puissants que le scanner"}],"multiple":false},{"enonce":"Complète avec les bons termes médicaux.","aide":"Hanche = cox(o), genou = gon(o), puis arthrose.","type":"trous","segments":["L’arthrose de la hanche s’appelle la ",0," et celle du genou la ",1,"."],"banque":["gonarthrose","coxarthrose","tendinite","ostéoporose"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c2","i3":"c0"}},"explication":"Karim : **radiographie** (simple, rapide). Julie : **IRM** (ligament = tissu mou). Marc : **scanner** (fractures complexes, coupes sans superposition). Mme Roux : **IRM**, qui n’emploie aucun rayonnement ionisant."},{"cle":{"type":"zone","ids":["r0c3"]},"explication":"La radiographie utilise des rayons X **ionisants** : elle est **en principe contre-indiquée chez la femme enceinte**."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’**IRM** est **contre-indiquée** avec des éclats métalliques : le champ magnétique pourrait les déplacer. On choisira la radiographie ou le scanner."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’**IRM** est excellente pour les **tissus mous** (ligaments, ménisques, moelle, encéphale) et n’utilise aucun rayonnement ionisant. Elle est longue et bruyante."},{"cle":{"type":"trous","trous":[["coxarthrose"],["gonarthrose"]]},"affichage":"coxarthrose · gonarthrose","explication":"**Cox(o)** = hanche donne la **coxarthrose** ; **gon(o)** = genou donne la **gonarthrose**. L’ostéoporose, elle, est une fragilisation de l’os."}]$ex$::jsonb),
  ('2ed30fa5-823c-5eb9-935a-dbfab4eacdc9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un neurone, du message reçu au message transmis","competence":"observer-schema","situation":"Dans son cahier de biologie, Ilyès dessine un neurone moteur. Il veut retrouver ses parties et le chemin suivi par l’influx nerveux.","documents":[{"id":"neurone","type":"schema","titre":"Un neurone (schéma simplifié)","largeur":340,"hauteur":210,"elements":[{"forme":"ligne","de":[58,92],"a":[22,55],"teinte":"violet"},{"forme":"ligne","de":[52,105],"a":[14,105],"teinte":"violet"},{"forme":"ligne","de":[58,118],"a":[22,158],"teinte":"violet"},{"forme":"cercle","cx":82,"cy":105,"r":28,"teinte":"violet","motif":"clair","id":"z1","zone":true},{"forme":"cercle","cx":82,"cy":105,"r":10,"teinte":"violet","motif":"plein"},{"forme":"rect","x":110,"y":99,"l":160,"h":12,"teinte":"ambre","motif":"clair","id":"z2","zone":true},{"forme":"ligne","de":[270,105],"a":[308,70],"teinte":"violet"},{"forme":"ligne","de":[270,105],"a":[316,105],"teinte":"violet"},{"forme":"ligne","de":[270,105],"a":[308,140],"teinte":"violet"},{"forme":"cercle","cx":310,"cy":68,"r":5,"teinte":"violet","motif":"plein"},{"forme":"cercle","cx":320,"cy":105,"r":5,"teinte":"violet","motif":"plein"},{"forme":"cercle","cx":310,"cy":142,"r":5,"teinte":"violet","motif":"plein"},{"forme":"texte","x":170,"y":190,"texte":"Les dendrites sont à gauche, les terminaisons à droite","taille":"petit","italique":true,"ancre":"milieu"}]}],"questions":[{"enonce":"Touche le corps cellulaire, la partie qui contient le noyau.","aide":"C’est la zone arrondie, avec un petit rond plein en son centre.","type":"zone","document":"neurone","multiple":false},{"enonce":"Touche le long prolongement unique qui conduit l’influx vers les terminaisons.","aide":"Les dendrites sont courtes et nombreuses ; celui-ci est long et unique.","type":"zone","document":"neurone","multiple":false},{"enonce":"Range ces parties dans l’ordre où l’influx nerveux les traverse.","aide":"Les dendrites reçoivent le message, les terminaisons le transmettent à la cellule suivante.","type":"ordre","items":[{"id":"a","texte":"Arborisation terminale"},{"id":"b","texte":"Corps cellulaire"},{"id":"c","texte":"Axone"},{"id":"d","texte":"Dendrites"}]}]}$ex$::jsonb,
