   $ex${"titre":"Un enregistrement de potentiel d’action","competence":"lire-graphique","situation":"Au laboratoire, une étudiante enregistre l’activité électrique d’une fibre nerveuse après l’avoir stimulée. Elle obtient une courbe et un tableau de mesures à interpréter.","documents":[{"id":"pa","type":"graphique","forme":"courbe","titre":"Potentiel de membrane d’une fibre nerveuse stimulée à t = 0,5 ms","categories":["0","0,5","1","1,5","2","2,5","3","3,5","4"],"series":[{"nom":"Potentiel","valeurs":[-70,-70,-50,30,-10,-75,-72,-70,-70],"teinte":"violet"}],"axeY":{"titre":"Potentiel de membrane","unite":"mV","min":-80,"max":40,"pas":10},"axeX":{"titre":"Temps (ms)"},"valeurs":false,"source":"Enregistrement idéalisé"},{"id":"stim","type":"tableau","titre":"La même fibre, quatre stimulations d’intensité croissante","colonnes":["Intensité (unités arbitraires)","Potentiel d’action ?","Amplitude du PA","PA par seconde"],"lignes":[["0,5","non","aucun","0"],["1","oui","100 mV","10"],["2","oui","100 mV","20"],["4","oui","100 mV","40"]],"enteteLignes":true,"source":"Mesures imaginées pour l’exercice"}],"questions":[{"enonce":"Lis la valeur du potentiel de repos de cette fibre, avant la stimulation.","aide":"Regarde la valeur à t = 0, avant que quoi que ce soit ne se passe.","type":"nombre","unite":"mV"},{"enonce":"Touche l’instant où la fibre est le plus dépolarisée (le sommet du potentiel d’action).","aide":"Cherche le point le plus haut de la courbe.","type":"zone","document":"pa","multiple":false},{"enonce":"De combien de millivolts le potentiel monte-t-il entre le repos et le sommet ?","aide":"Calcule 30 − (−70).","type":"nombre","unite":"mV"},{"enonce":"Touche l’instant de l’hyperpolarisation, où le potentiel passe sous le potentiel de repos.","aide":"Cherche le point le plus bas de la courbe.","type":"zone","document":"pa","multiple":false},{"enonce":"Que montre le tableau quand on augmente l’intensité de stimulation d’une même fibre ?","aide":"Compare la colonne « Amplitude » et la colonne « PA par seconde » ligne après ligne.","type":"choix","options":[{"id":"a","texte":"Amplitude constante, fréquence croissante avec l’intensité"},{"id":"b","texte":"La fréquence des PA ne dépend pas de l’intensité"},{"id":"c","texte":"L’amplitude du PA grandit avec l’intensité de stimulation"},{"id":"d","texte":"Le PA disparaît si la stimulation devient trop forte"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":-70,"tolerance":2},"affichage":"−70 mV","explication":"Le potentiel de repos est d’environ **−70 mV** : l’intérieur de la fibre est négatif par rapport à l’extérieur."},{"cle":{"type":"zone","ids":["k3"]},"explication":"Le sommet est atteint à **1,5 ms** : l’intérieur de la fibre est alors positif (+30 mV)."},{"cle":{"type":"nombre","valeur":100,"tolerance":0},"affichage":"100 mV","explication":"30 − (−70) = **100 mV** : c’est l’amplitude du potentiel d’action de cette fibre."},{"cle":{"type":"zone","ids":["k5"]},"explication":"À **2,5 ms**, le potentiel descend à −75 mV, sous le repos de −70 mV : c’est l’**hyperpolarisation**, avant le retour au repos."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’amplitude reste à 100 mV (loi du **tout ou rien**) : l’intensité est codée par la **fréquence** des potentiels d’action."}]$ex$::jsonb),
  ('2ed30fa5-823c-5eb9-935a-dbfab4eacdc9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Pourquoi la réponse d’un nerf grandit avec la stimulation","competence":"raisonner","situation":"Un chercheur stimule un nerf de plus en plus fort et mesure la réponse globale. Le nerf ne contient que quatre fibres, de seuils différents ; chacune qui répond ajoute 1 mV à la réponse.","documents":[{"id":"seuils","type":"tableau","titre":"Les quatre fibres du nerf","colonnes":["Fibre","Seuil de stimulation (V)"],"lignes":[["A","1"],["B","2"],["C","3,5"],["D","5"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"rep","type":"graphique","forme":"courbe","titre":"Réponse globale du nerf","categories":["0","1","2","3","4","5","6"],"series":[{"nom":"Réponse","valeurs":[0,1,2,2,3,4,4],"teinte":"turquoise"}],"axeY":{"titre":"Réponse du nerf","unite":"mV","min":0,"max":5,"pas":1},"axeX":{"titre":"Intensité de la stimulation (V)"},"valeurs":false}],"questions":[{"enonce":"Combien de fibres répondent à une stimulation de 4 V ?","aide":"Une fibre répond si l’intensité atteint son seuil.","type":"nombre","unite":"fibres"},{"enonce":"Touche la plus petite intensité qui donne la réponse maximale.","aide":"Cherche la première fois où la courbe atteint son niveau le plus haut.","type":"zone","document":"rep","multiple":false},{"enonce":"Pourquoi la courbe ne monte-t-elle plus au-delà de 5 V ?","aide":"Compare 5 V au seuil de la dernière fibre du tableau.","type":"choix","options":[{"id":"a","texte":"Les fibres se fatiguent et cessent de répondre"},{"id":"b","texte":"La loi du tout ou rien ne s’applique plus au nerf"},{"id":"c","texte":"La gaine de myéline bloque les fortes stimulations"},{"id":"d","texte":"Toutes les fibres du nerf répondent déjà"}],"multiple":false},{"enonce":"On stimule une seule de ces fibres, d’abord à 2 V puis à 6 V. Que change-t-on dans sa réponse ?","aide":"Une fibre isolée obéit à la loi du tout ou rien : que code l’intensité ?","type":"choix","options":[{"id":"a","texte":"Son amplitude et sa fréquence restent toutes deux constantes"},{"id":"b","texte":"Elle ne répond plus au-dessus de 5 V"},{"id":"c","texte":"Son amplitude reste la même, sa fréquence augmente"},{"id":"d","texte":"Son amplitude augmente, sa fréquence reste la même"}],"multiple":false},{"enonce":"Associe chaque situation à ce qu’elle produit.","aide":"Distingue la fibre seule, le nerf entier, et ce qui se passe sous le seuil.","type":"association","gauche":[{"id":"g0","texte":"Une stimulation sous le seuil"},{"id":"g1","texte":"Une fibre isolée bien stimulée"},{"id":"g2","texte":"Le nerf entier de plus en plus stimulé"},{"id":"g3","texte":"Une fibre à gaine de myéline"}],"droite":[{"id":"d0","texte":"Aucun potentiel d’action"},{"id":"d1","texte":"Recrutement de fibres"},{"id":"d2","texte":"PA d’amplitude constante"},{"id":"d3","texte":"Conduction plus rapide"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 fibres","explication":"À 4 V, les fibres **A (1 V), B (2 V) et C (3,5 V)** ont atteint leur seuil : **3 fibres** répondent ; D (5 V) reste silencieuse."},{"cle":{"type":"zone","ids":["k5"]},"explication":"À **5 V**, la quatrième fibre (seuil 5 V) répond : la réponse atteint 4 mV, son maximum."},{"cle":{"type":"choix","ids":["d"]},"explication":"Au-delà de 5 V, il n’y a plus de fibre à **recruter** : la réponse du nerf plafonne à son **maximum**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Pour une fibre isolée, l’amplitude du PA est constante (**tout ou rien**) : l’intensité est codée par la **fréquence**. Seul le nerf, qui contient plusieurs fibres, grandit par recrutement."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"Sous le seuil, **pas de PA** ; une fibre obéit au **tout ou rien** ; un nerf grandit par **recrutement** ; la **myéline** accélère la conduction (de nœud en nœud)."}]$ex$::jsonb),
  ('08f314d7-2cd2-5b3b-863b-8732c7abec7c'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le biceps de Naël, du muscle à la fibre","competence":"analyser-texte","situation":"Naël soulève son sac de sport. Son professeur de biologie lui fait lire une description du muscle qui travaille.","documents":[{"id":"biceps","type":"texte","genre":"article","titre":"Un biceps vu de près","auteur":"Texte écrit pour l’exercice","blocs":["Quand Naël plie le bras, son biceps se raccourcit. Ce muscle est prolongé de chaque côté par des tendons qui l’accrochent solidement aux os.","Au microscope, le muscle se révèle fait de faisceaux, eux-mêmes composés de longues cellules appelées fibres.","Chaque fibre contient plusieurs noyaux, de nombreuses mitochondries et des centaines de myofibrilles rayées : c’est ce qui donne au muscle son aspect strié."]}],"questions":[{"enonce":"Touche le mot qui désigne ce qui relie le muscle à l’os.","aide":"Il est dans la première phrase, après « prolongé de chaque côté par des ».","type":"zone","document":"biceps","multiple":false},{"enonce":"Touche le mot qui désigne la cellule du muscle.","aide":"Cherche « longues cellules appelées… ».","type":"zone","document":"biceps","multiple":false},{"enonce":"Range ces niveaux d’organisation du plus grand au plus petit.","aide":"Chaque niveau est contenu dans le précédent ; le texte te donne les premiers.","type":"ordre","items":[{"id":"a","texte":"Muscle"},{"id":"b","texte":"Fibre musculaire"},{"id":"c","texte":"Myofibrille"},{"id":"d","texte":"Sarcomère"},{"id":"e","texte":"Faisceau"}]},{"enonce":"Complète la phrase.","aide":"C’est la molécule énergétique produite par la respiration cellulaire.","type":"trous","segments":["Les mitochondries de la fibre produisent l’",0," dont la contraction a besoin."],"banque":["collagène","ATP","ADN","acétylcholine"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"Les **tendons** relient les muscles aux os ; les ligaments, eux, relient les os entre eux."},{"cle":{"type":"zone","ids":["m40"]},"explication":"La **fibre musculaire** est la cellule du muscle : une cellule géante, très longue, à plusieurs noyaux."},{"cle":{"type":"ordre","ids":["a","e","b","c","d"]},"explication":"Le **muscle** contient des **faisceaux**, faits de **fibres**, qui renferment des **myofibrilles**, elles-mêmes composées de **sarcomères**."},{"cle":{"type":"trous","trous":[["atp"]]},"affichage":"ATP","explication":"La contraction consomme de l’**ATP**, produit par les mitochondries : la fibre musculaire en est très riche."}]$ex$::jsonb),
  ('08f314d7-2cd2-5b3b-863b-8732c7abec7c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le sarcomère avant et pendant la contraction","competence":"observer-schema","situation":"Camille étudie la contraction musculaire à l’échelle du sarcomère. Elle dispose d’un schéma du sarcomère au repos et des mesures prises quand il est contracté.","documents":[{"id":"sarco","type":"schema","titre":"Un sarcomère au repos (schéma)","largeur":340,"hauteur":190,"elements":[{"forme":"rect","x":40,"y":14,"l":56,"h":14,"teinte":"jaune","motif":"clair","id":"z1","zone":true},{"forme":"rect","x":96,"y":14,"l":148,"h":14,"teinte":"violet","motif":"plein","id":"z2","zone":true},{"forme":"rect","x":244,"y":14,"l":56,"h":14,"teinte":"jaune","motif":"clair","id":"z3","zone":true},{"forme":"rect","x":38,"y":40,"l":8,"h":80,"teinte":"encre","motif":"plein"},{"forme":"rect","x":294,"y":40,"l":8,"h":80,"teinte":"encre","motif":"plein"},{"forme":"ligne","de":[46,50],"a":[150,50],"teinte":"bleu"},{"forme":"ligne","de":[190,50],"a":[294,50],"teinte":"bleu"},{"forme":"rect","x":96,"y":60,"l":148,"h":7,"arrondi":3,"teinte":"corail","motif":"plein"},{"forme":"ligne","de":[46,80],"a":[150,80],"teinte":"bleu"},{"forme":"ligne","de":[190,80],"a":[294,80],"teinte":"bleu"},{"forme":"rect","x":96,"y":90,"l":148,"h":7,"arrondi":3,"teinte":"corail","motif":"plein"},{"forme":"ligne","de":[46,110],"a":[150,110],"teinte":"bleu"},{"forme":"ligne","de":[190,110],"a":[294,110],"teinte":"bleu"},{"forme":"rect","x":150,"y":128,"l":40,"h":14,"teinte":"turquoise","motif":"clair","id":"z4","zone":true},{"forme":"texte","x":170,"y":168,"texte":"Traits fins : actine · traits épais : myosine · barres noires : stries Z","taille":"petit","italique":true,"ancre":"milieu"}]},{"id":"mesures","type":"tableau","titre":"Mesures sur un sarcomère","colonnes":["Mesure","Au repos (µm)","Contracté (µm)"],"lignes":[["Sarcomère","2,5","2,0"],["Bande A","1,6","1,6"],["Bande I","0,9","0,4"],["Zone H","0,4","0 (a disparu)"]],"enteteLignes":true,"source":"Mesures idéalisées pour l’exercice"}],"questions":[{"enonce":"Touche les deux valeurs qui ne changent pas entre le repos et la contraction.","aide":"Compare les deux colonnes ligne par ligne : une seule ligne est identique.","type":"zone","document":"mesures","multiple":true},{"enonce":"De combien le sarcomère se raccourcit-il pendant la contraction ?","aide":"Soustrais la valeur contractée à la valeur au repos.","type":"nombre","unite":"µm"},{"enonce":"Touche la zone du sarcomère où il n’y a que des filaments de myosine.","aide":"Elle se trouve au centre, là où les filaments d’actine ne se rejoignent pas.","type":"zone","document":"sarco","multiple":false},{"enonce":"Que se passe-t-il pour les filaments d’actine et de myosine pendant la contraction ?","aide":"La bande A, qui correspond à la myosine, garde la même longueur.","type":"choix","options":[{"id":"a","texte":"Les filaments de myosine disparaissent peu à peu"},{"id":"b","texte":"Les filaments d’actine se replient sur eux-mêmes"},{"id":"c","texte":"Ils glissent les uns sur les autres sans changer de longueur"},{"id":"d","texte":"Ils raccourcissent tous les deux de la même longueur"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1","r1c2"]},"explication":"La **bande A** garde ses **1,6 µm** : les filaments de myosine ne raccourcissent pas."},{"cle":{"type":"nombre","valeur":0.5,"tolerance":0},"affichage":"0,5 µm","explication":"2,5 − 2,0 = **0,5 µm** : le sarcomère se raccourcit, mais pas la bande A."},{"cle":{"type":"zone","ids":["z4"]},"explication":"La **zone H**, au centre de la bande A, ne contient que de la myosine. Elle diminue puis disparaît quand les filaments glissent."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les têtes de **myosine** tirent l’**actine** vers le centre : les filaments **glissent**, sans raccourcir, ce qui diminue la bande I et la zone H."}]$ex$::jsonb),
  ('08f314d7-2cd2-5b3b-863b-8732c7abec7c'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quand la commande nerveuse arrive à la fibre","competence":"raisonner","situation":"Un laboratoire étudie la jonction entre un motoneurone et une fibre musculaire. Il teste deux toxines imaginées, A et B, pour comprendre le rôle de chaque étape.","documents":[{"id":"jonction","type":"schema","titre":"La jonction neuromusculaire (schéma)","largeur":320,"hauteur":280,"elements":[{"forme":"rect","x":60,"y":14,"l":200,"h":90,"arrondi":14,"teinte":"violet","motif":"clair"},{"forme":"cercle","cx":110,"cy":66,"r":12,"teinte":"jaune","motif":"plein"},{"forme":"cercle","cx":160,"cy":76,"r":12,"teinte":"jaune","motif":"plein"},{"forme":"cercle","cx":210,"cy":66,"r":12,"teinte":"jaune","motif":"plein"},{"forme":"texte","x":160,"y":36,"texte":"Terminaison du motoneurone","taille":"petit","ancre":"milieu"},{"forme":"rect","x":60,"y":104,"l":200,"h":30,"teinte":"turquoise","motif":"clair","id":"z1","zone":true},{"forme":"cercle","cx":120,"cy":118,"r":3,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":160,"cy":122,"r":3,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":200,"cy":118,"r":3,"teinte":"ambre","motif":"plein"},{"forme":"rect","x":60,"y":134,"l":200,"h":120,"teinte":"rose","motif":"clair"},{"forme":"rect","x":80,"y":134,"l":26,"h":12,"teinte":"corail","motif":"plein","id":"z2","zone":true},{"forme":"rect","x":147,"y":134,"l":26,"h":12,"teinte":"corail","motif":"plein","id":"z3","zone":true},{"forme":"rect","x":214,"y":134,"l":26,"h":12,"teinte":"corail","motif":"plein","id":"z4","zone":true},{"forme":"texte","x":160,"y":205,"texte":"Fibre musculaire","taille":"petit","ancre":"milieu"}]},{"id":"toxines","type":"tableau","titre":"Ce que bloque chaque toxine","colonnes":["Cas","ACh libérée","Récepteurs","Enzyme"],"lignes":[["Sans toxine","oui","libres","active"],["Toxine A","oui","bloqués","active"],["Toxine B","oui","libres","bloquée"]],"enteteLignes":true,"source":"Toxines imaginées pour l’exercice. ACh : acétylcholine ; l’enzyme dégrade l’ACh."}],"questions":[{"enonce":"Touche l’espace dans lequel l’acétylcholine est libérée.","aide":"C’est l’espace étroit qui sépare le neurone de la fibre.","type":"zone","document":"jonction","multiple":false},{"enonce":"Touche les récepteurs sur lesquels l’acétylcholine se fixe.","aide":"Ils sont sur la membrane de la fibre musculaire, au contact de la fente. Il y en a trois.","type":"zone","document":"jonction","multiple":true},{"enonce":"Range les étapes de la commande du muscle dans l’ordre.","aide":"Le message est électrique, puis chimique dans la fente, puis de nouveau électrique.","type":"ordre","items":[{"id":"a","texte":"Les vésicules libèrent l’acétylcholine dans la fente"},{"id":"b","texte":"Un potentiel d’action arrive à la terminaison du motoneurone"},{"id":"c","texte":"Les myofilaments glissent : la fibre se contracte"},{"id":"d","texte":"L’acétylcholine se fixe sur les récepteurs de la fibre"},{"id":"e","texte":"Un potentiel d’action musculaire libère le calcium"}]},{"enonce":"Avec la toxine A, des motoneurones sont stimulés. Que devient la contraction de la fibre ?","aide":"Regarde la colonne « Récepteurs » pour la toxine A.","type":"choix","options":[{"id":"a","texte":"Elle reste normale : l’acétylcholine agit quand même"},{"id":"b","texte":"Elle est impossible : l’acétylcholine ne se fixe plus"},{"id":"c","texte":"Elle se prolonge : l’acétylcholine n’est plus dégradée"},{"id":"d","texte":"Elle se déclenche seule, sans commande nerveuse"}],"multiple":false},{"enonce":"Avec la toxine B, quelle est la conséquence ?","aide":"Quel est le rôle de l’acétylcholinestérase ? Que se passe-t-il quand elle est bloquée ?","type":"choix","options":[{"id":"a","texte":"Elle est impossible : l’acétylcholine ne se fixe plus"},{"id":"b","texte":"Elle se déclenche seule, sans commande nerveuse"},{"id":"c","texte":"Elle se prolonge : l’acétylcholine n’est plus dégradée"},{"id":"d","texte":"Elle reste normale : l’acétylcholine agit quand même"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Les vésicules libèrent l’acétylcholine dans la **fente synaptique**, qui sépare la terminaison du motoneurone de la fibre musculaire."},{"cle":{"type":"zone","ids":["z2","z3","z4"]},"explication":"Les **récepteurs** sont sur la membrane de la fibre : la fixation de l’acétylcholine y déclenche un potentiel d’action musculaire."},{"cle":{"type":"ordre","ids":["b","a","d","e","c"]},"explication":"Message **électrique** à la terminaison, **chimique** dans la fente (acétylcholine), puis **électrique** sur la fibre, qui libère le calcium et se contracte."},{"cle":{"type":"choix","ids":["b"]},"explication":"Récepteurs bloqués : l’acétylcholine, bien libérée, **ne peut plus se fixer** ; aucun potentiel d’action musculaire n’apparaît, la fibre ne se contracte pas."},{"cle":{"type":"choix","ids":["c"]},"explication":"Sans **acétylcholinestérase**, l’acétylcholine n’est plus dégradée : elle reste dans la fente et la commande **ne s’arrête pas**."}]$ex$::jsonb),
  ('b313e368-2157-5371-9192-43b3284d19c4'::uuid, 1, 1, 5, 20, 3,
