  ('b313e368-2157-5371-9192-43b3284d19c4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Mme Garnier, le bras qui ne répond plus","competence":"analyser-document","situation":"Mme Garnier, 68 ans, s’effondre dans sa cuisine : son bras et sa jambe droits ne bougent plus et ses mots sont confus. À l’hôpital, l’IRM montre l’atteinte d’une artère du cerveau.","documents":[{"id":"cerveau","type":"schema","titre":"Cerveau vu de face, comme sur une image médicale","largeur":320,"hauteur":220,"elements":[{"forme":"ellipse","cx":110,"cy":100,"rx":72,"ry":68,"teinte":"rose","motif":"clair","id":"z1","zone":true},{"forme":"ellipse","cx":210,"cy":100,"rx":72,"ry":68,"teinte":"rose","motif":"clair","id":"z2","zone":true},{"forme":"texte","x":70,"y":200,"texte":"Droite du patient","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"texte","x":250,"y":200,"texte":"Gauche du patient","taille":"petit","italique":true,"ancre":"milieu"}],"source":"Convention : la droite du patient est à gauche de l’image"},{"id":"types","type":"tableau","titre":"Les deux types d’AVC","colonnes":["Type","Mécanisme","Fréquence"],"lignes":[["Ischémique","artère bouchée par un caillot","environ 80 %"],["Hémorragique","artère rompue, le sang se répand","environ 20 %"]],"enteteLignes":true}],"questions":[{"enonce":"Mme Garnier est paralysée du côté droit. Touche l’hémisphère touché par l’AVC.","aide":"Chaque hémisphère commande la moitié opposée du corps ; et lis bien la légende sous le schéma.","type":"zone","document":"cerveau","multiple":false},{"enonce":"Comment s’appelle le trouble de la parole de Mme Garnier, dû à l’atteinte de l’hémisphère gauche ?","aide":"Chez la plupart des droitiers, le langage dépend de l’hémisphère gauche.","type":"choix","options":[{"id":"a","texte":"Une paraplégie"},{"id":"b","texte":"Une paresthésie"},{"id":"c","texte":"Une aphasie"},{"id":"d","texte":"Une amnésie"}],"multiple":false},{"enonce":"Sur 200 AVC, combien sont ischémiques environ ?","aide":"Calcule 80 % de 200.","type":"nombre","unite":"AVC"},{"enonce":"L’IRM montre une artère bouchée par un caillot. De quel type d’AVC s’agit-il, et que cherche-t-on à faire ?","aide":"Un caillot qui bouche une artère : lis la ligne « Mécanisme » du tableau.","type":"choix","options":[{"id":"a","texte":"Hémorragique : boucher l’artère qui saigne sans imagerie"},{"id":"b","texte":"Ischémique : attendre que le caillot disparaisse seul"},{"id":"c","texte":"Ischémique : dissoudre ou retirer le caillot en urgence"},{"id":"d","texte":"Hémorragique : dissoudre ou retirer le caillot en urgence"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le côté droit du corps est commandé par l’hémisphère **gauche**, qui apparaît **à droite** de l’image selon la convention médicale."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’**aphasie** est un trouble du langage. L’amnésie est une perte de mémoire, la paresthésie des fourmillements, la paraplégie une paralysie des jambes."},{"cle":{"type":"nombre","valeur":160,"tolerance":0},"affichage":"160 AVC","explication":"200 × 0,80 = **160** AVC ischémiques ; les 40 autres sont hémorragiques."},{"cle":{"type":"choix","ids":["c"]},"explication":"Une artère **bouchée** est un AVC **ischémique** ; on traite par **thrombolyse** (dissoudre) ou **thrombectomie** (retirer), dans les toutes premières heures."}]$ex$::jsonb),
  ('b313e368-2157-5371-9192-43b3284d19c4'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Trois patients aux urgences, un diagnostic à poser","competence":"raisonner","situation":"Le même soir, trois patients arrivent aux urgences. L’interne doit distinguer une lésion de la moelle épinière d’un AVC, nommer chaque atteinte, puis repérer chez l’un d’eux les facteurs de risque.","documents":[{"id":"patients","type":"tableau","titre":"Ce que racontent les témoins","colonnes":["Patient","Ce qui s’est passé"],"lignes":[["Lucas, 19 ans","Chute de moto : il ne sent plus ses jambes, mais bouge les bras et respire normalement"],["Mme Blanc","Brutalement, le côté gauche du visage et le bras gauche ne répondent plus, la parole est confuse"],["M. Perrin, 55 ans","Plongeon en eau peu profonde : il ne bouge plus ni bras ni jambes et respire avec difficulté"]],"enteteLignes":true,"source":"Patients fictifs"},{"id":"dossier","type":"texte","genre":"article","titre":"Le dossier du médecin traitant de Mme Blanc","auteur":"Texte écrit pour l’exercice","blocs":["Mme Blanc vit seule et adore le jardinage. Depuis des années, sa hypertension n’est pas soignée, et elle fume encore un paquet de tabac par jour.","Son taux de cholestérol est trop élevé et elle marche très peu : sa sédentarité est marquée. En revanche, elle mange du poisson deux fois par semaine et dort bien."]}],"questions":[{"enonce":"Classe chaque patient : lésion de la moelle épinière ou AVC ?","aide":"Un accident violent du dos ou du cou touche la moelle ; un trouble brutal sans choc, avec parole confuse, évoque l’AVC.","type":"categories","categories":[{"id":"c0","texte":"Lésion de la moelle épinière"},{"id":"c1","texte":"AVC"}],"items":[{"id":"i0","texte":"Mme Blanc"},{"id":"i1","texte":"Lucas"},{"id":"i2","texte":"M. Perrin"}]},{"enonce":"Associe chaque patient au terme qui décrit son atteinte.","aide":"Deux jambes, quatre membres, ou une moitié du corps.","type":"association","gauche":[{"id":"g0","texte":"Lucas"},{"id":"g1","texte":"M. Perrin"},{"id":"g2","texte":"Mme Blanc"}],"droite":[{"id":"d0","texte":"Tétraplégie"},{"id":"d1","texte":"Paraplégie"},{"id":"d2","texte":"Hémiplégie gauche"}]},{"enonce":"Mme Blanc est paralysée du côté gauche. Quelle partie de son encéphale est probablement touchée ?","aide":"Chaque hémisphère commande la moitié opposée du corps.","type":"choix","options":[{"id":"a","texte":"L’hémisphère cérébral gauche"},{"id":"b","texte":"Le nerf sciatique gauche"},{"id":"c","texte":"La moelle épinière cervicale"},{"id":"d","texte":"L’hémisphère cérébral droit"}],"multiple":false},{"enonce":"Touche tous les facteurs de risque d’AVC cités dans le dossier de Mme Blanc.","aide":"Il y en a quatre : une tension, une habitude, une substance dans le sang, un mode de vie.","type":"zone","document":"dossier","multiple":true},{"enonce":"Pourquoi M. Perrin respire-t-il difficilement alors que Lucas respire normalement ?","aide":"Plus la lésion est haute, plus elle prive de commande des muscles importants, dont ceux de la respiration.","type":"choix","options":[{"id":"a","texte":"Sa lésion est très haute, au niveau cervical, et gêne la respiration"},{"id":"b","texte":"Sa lésion est basse, au niveau lombaire, et gêne la respiration"},{"id":"c","texte":"Il avale de l’eau parce que ses jambes sont paralysées"},{"id":"d","texte":"Il a eu un AVC hémorragique pendant son plongeon"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0"}},"explication":"Lucas et M. Perrin ont subi un traumatisme du **rachis** : lésion de la **moelle épinière**. Les signes brutaux de Mme Blanc évoquent un **AVC**."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Lucas : **paraplégie** (jambes). M. Perrin : **tétraplégie** (quatre membres). Mme Blanc : **hémiplégie gauche** (moitié gauche du corps)."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’hémisphère **droit** commande la moitié **gauche** du corps : une lésion de l’hémisphère droit provoque une hémiplégie gauche."},{"cle":{"type":"zone","ids":["m12","m24","m30","m40"]},"explication":"**Hypertension** (le premier facteur de risque), **tabac**, **cholestérol** excessif et **sédentarité** augmentent le risque d’AVC. Le poisson et le sommeil n’en sont pas."},{"cle":{"type":"choix","ids":["a"]},"explication":"Une lésion **cervicale très haute** touche la respiration ; la lésion de Lucas, plus basse, épargne la respiration et les bras."}]$ex$::jsonb),
