  ('08d37f26-a2e2-5153-abf2-a5073a2c98dc'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’IMC de quatre adultes et d’une adolescente","competence":"calculer","situation":"Au centre de santé, une infirmière a noté la masse et la taille de cinq personnes. Elle t’aide à calculer et à interpréter leur indice de masse corporelle (IMC).","documents":[{"id":"personnes","type":"tableau","titre":"Les mesures du jour","colonnes":["Prénom","Masse (kg)","Taille (m)","IMC (kg/m²)"],"lignes":[["Thomas, adulte","72","1,80","?"],["Samia, adulte","49","1,70","17,0"],["Hugo, adulte","95","1,75","31,0"],["Léa, adulte","78","1,70","27,0"],["Inès, 14 ans","50","1,60","19,5"]],"enteteLignes":true,"source":"Mesures imaginées, IMC arrondis au dixième"},{"id":"seuils","type":"tableau","titre":"Interpréter l’IMC d’un adulte","colonnes":["IMC","Interprétation"],"lignes":[["moins de 18,5","Maigreur"],["de 18,5 à moins de 25","Corpulence normale"],["de 25 à moins de 30","Surpoids"],["30 et plus","Obésité"]],"enteteLignes":true}],"questions":[{"enonce":"Calcule l’IMC de Thomas (masse ÷ taille²), arrondi au dixième.","aide":"Calcule d’abord 1,80 × 1,80, puis divise 72 par ce résultat.","type":"nombre","unite":"kg/m²"},{"enonce":"Classe chaque adulte selon son IMC.","aide":"Compare chaque IMC aux seuils du second tableau : 18,5, 25 et 30.","type":"categories","categories":[{"id":"c0","texte":"Maigreur"},{"id":"c1","texte":"Normale"},{"id":"c2","texte":"Surpoids"},{"id":"c3","texte":"Obésité"}],"items":[{"id":"i0","texte":"Léa"},{"id":"i1","texte":"Thomas"},{"id":"i2","texte":"Hugo"},{"id":"i3","texte":"Samia"}]},{"enonce":"Quelle masse donnerait à Léa (1,70 m) un IMC de 25, limite du surpoids ?","aide":"IMC = masse ÷ taille², donc masse = IMC × taille².","type":"nombre","unite":"kg"},{"enonce":"Inès a 14 ans et un IMC de 19,5. Pourquoi ne la classe-t-on pas avec les seuils du tableau ?","aide":"Un adolescent grandit : sa corpulence normale change avec l’âge.","type":"choix","options":[{"id":"a","texte":"Chez l’adolescent, l’IMC ne peut pas être calculé avec la taille"},{"id":"b","texte":"Chez l’adolescent, seule la masse compte, pas la taille"},{"id":"c","texte":"Chez l’adolescent, les seuils sont toujours plus élevés de 5"},{"id":"d","texte":"Chez l’adolescent, l’IMC se lit sur des courbes selon l’âge et le sexe"}],"multiple":false}]}$ex$::jsonb,
