  ('08d37f26-a2e2-5153-abf2-a5073a2c98dc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le bilan énergétique d’un joueur de rugby","competence":"raisonner","situation":"Maxime, 17 ans, joue au rugby. Son diététicien lui a fait noter ce qu’il mange et estimer ce qu’il dépense en une journée d’entraînement. Tu fais le bilan.","documents":[{"id":"journee","type":"tableau","titre":"Une journée de Maxime","colonnes":["Apports","kcal","Dépenses","kcal"],"lignes":[["Petit-déjeuner","650","Métabolisme de base","1 700"],["Déjeuner","900","Activité physique (rugby compris)","1 200"],["Goûter","400","Thermorégulation et autres","100"],["Dîner","850","",""]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"repart","type":"graphique","forme":"secteurs","titre":"D’où vient l’énergie de ses repas","categories":["Glucides","Lipides","Protéines"],"series":[{"nom":"Part de l’énergie","valeurs":[50,35,15],"teinte":"violet"}],"source":"Parts de l’énergie apportée, en %"}],"questions":[{"enonce":"Touche le macronutriment qui fournit la plus grande part de l’énergie de Maxime.","aide":"Cherche le plus grand secteur.","type":"zone","document":"repart","multiple":false},{"enonce":"Quel est le total des apports énergétiques de la journée de Maxime ?","aide":"Additionne les quatre repas de la colonne « Apports ».","type":"nombre","unite":"kcal"},{"enonce":"Calcule le bilan énergétique de la journée (apports − dépenses). Un résultat négatif s’écrit avec un signe moins.","aide":"Additionne d’abord les trois dépenses, puis soustrais-les des apports.","type":"nombre","unite":"kcal"},{"enonce":"Combien de kilocalories viennent des glucides dans les 2 800 kcal de la journée ?","aide":"Lis la part des glucides dans le graphique, puis calcule ce pourcentage de 2 800.","type":"nombre","unite":"kcal"},{"enonce":"Si ce bilan se répétait chaque jour pendant des mois, que risquerait-il d’arriver à Maxime ?","aide":"Le bilan est négatif : l’organisme dépense plus d’énergie qu’il n’en reçoit.","type":"choix","options":[{"id":"a","texte":"Une carence en eau, car l’eau ne figure pas au bilan"},{"id":"b","texte":"Un amaigrissement, car les dépenses dépassent les apports"},{"id":"c","texte":"Une prise de poids, car les apports dépassent les dépenses"},{"id":"d","texte":"Rien, car son bilan est positif à long terme"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Les **glucides** fournissent **50 %** de l’énergie, la plus grande part (comme chez la plupart des adultes : 40 à 55 %)."},{"cle":{"type":"nombre","valeur":2800,"tolerance":0},"affichage":"2800 kcal","explication":"650 + 900 + 400 + 850 = **2 800 kcal**."},{"cle":{"type":"nombre","valeur":-200,"tolerance":0},"affichage":"−200 kcal","explication":"Dépenses : 1 700 + 1 200 + 100 = 3 000 kcal. Bilan : 2 800 − 3 000 = **−200 kcal**."},{"cle":{"type":"nombre","valeur":1400,"tolerance":0},"affichage":"1400 kcal","explication":"50 % de 2 800 = **1 400 kcal**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Un bilan **négatif et durable** entraîne un **amaigrissement** ; un bilan positif durable, une prise de poids."}]$ex$::jsonb),
  ('959b38be-a7b5-572a-83d1-df70f9e37c35'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Camille, pâle et fatiguée, passe une prise de sang","competence":"lire-tableau","situation":"Camille, 16 ans, se sent très fatiguée et son entourage la trouve pâle. Elle s’essouffle vite à l’effort et ses règles sont abondantes. Son médecin demande une prise de sang.","documents":[{"id":"bilan","type":"tableau","titre":"Le bilan sanguin de Camille","colonnes":["Examen","Résultat de Camille","Valeurs usuelles (femme)"],"lignes":[["Hémoglobine","10,5 g/dL","12 à 16 g/dL"],["Ferritine","8 µg/L","15 à 150 µg/L"],["Glycémie à jeun","0,85 g/L","0,70 à 1,10 g/L"]],"enteteLignes":true,"source":"Patiente fictive, valeurs usuelles arrondies"}],"questions":[{"enonce":"Touche les deux résultats de Camille qui sont inférieurs aux valeurs usuelles.","aide":"Compare chaque résultat à la colonne de droite : la glycémie est normale.","type":"zone","document":"bilan","multiple":true},{"enonce":"Complète la phrase.","aide":"Un manque de fer fait baisser le taux de cette molécule dans le sang.","type":"trous","segments":["Le fer est nécessaire à la fabrication de l’",0,", qui transporte le dioxygène dans les globules rouges."],"banque":["insuline","collagène","hémoglobine","ferritine"]},{"enonce":"Que signifie une ferritine basse chez Camille ?","aide":"La ferritine est la forme de stockage du fer dans l’organisme.","type":"choix","options":[{"id":"a","texte":"Ses globules rouges sont trop nombreux"},{"id":"b","texte":"Son foie fabrique trop d’hémoglobine"},{"id":"c","texte":"Ses réserves de fer sont vides"},{"id":"d","texte":"Son corps contient trop de fer"}],"multiple":false}]}$ex$::jsonb,
