  ('959b38be-a7b5-572a-83d1-df70f9e37c35'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Kévin et six mois de rééquilibrage alimentaire","competence":"analyser-document","situation":"Kévin, 40 ans, consulte pour une prise de poids. Son médecin note ses habitudes et ses problèmes de santé, puis il le suit pendant six mois de rééquilibrage alimentaire.","documents":[{"id":"dossier","type":"texte","genre":"article","titre":"Le dossier de Kévin","auteur":"Texte écrit pour l’exercice","blocs":["Kévin mesure 1,75 m et pèse 98 kg. Il travaille assis toute la journée, boit plusieurs boissons sucrées par jour et dort peu.","Son médecin note une hypertension artérielle, une apnée du sommeil et une arthrose du genou qui le fait souffrir."]},{"id":"courbe","type":"graphique","forme":"courbe","titre":"La masse de Kévin pendant le suivi","categories":["Départ","Mois 1","Mois 2","Mois 3","Mois 4","Mois 5","Mois 6"],"series":[{"nom":"Masse","valeurs":[98,96,95,93,92,91,90],"teinte":"turquoise"}],"axeY":{"titre":"Masse","unite":"kg","min":85,"max":100,"pas":5},"axeX":{"titre":"Suivi"},"valeurs":false,"source":"Suivi imaginé pour l’exercice"}],"questions":[{"enonce":"Calcule l’IMC de Kévin au départ, arrondi au dixième.","aide":"IMC = masse ÷ taille². Calcule d’abord 1,75 × 1,75.","type":"nombre","unite":"kg/m²"},{"enonce":"Touche les trois mots qui désignent des conséquences pathologiques de l’obésité.","aide":"Ce sont des maladies que son médecin a notées : une pour la tension, une pour le sommeil, une pour l’articulation.","type":"zone","document":"dossier","multiple":true},{"enonce":"Calcule l’IMC de Kévin au mois 6, arrondi au dixième.","aide":"Lis sa masse à « Mois 6 » sur la courbe, puis reprends le même calcul.","type":"nombre","unite":"kg/m²"},{"enonce":"Avec cet IMC de 29,4, dans quelle catégorie se trouve maintenant Kévin ?","aide":"Rappelle-toi les seuils : 25 et 30.","type":"choix","options":[{"id":"a","texte":"Surpoids"},{"id":"b","texte":"Maigreur"},{"id":"c","texte":"Corpulence normale"},{"id":"d","texte":"Obésité"}],"multiple":false},{"enonce":"Associe chaque professionnel à sa place dans la prise en charge de Kévin.","aide":"La prise en charge de l’obésité est longue et pluridisciplinaire.","type":"association","gauche":[{"id":"g0","texte":"Diététicien"},{"id":"g1","texte":"Éducateur sportif"},{"id":"g2","texte":"Psychologue"},{"id":"g3","texte":"Médecin"}],"droite":[{"id":"d0","texte":"Accompagnement psychologique"},{"id":"d1","texte":"Coordonner le suivi et les traitements"},{"id":"d2","texte":"Rééquilibrer l’alimentation"},{"id":"d3","texte":"Augmenter l’activité physique"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":32,"tolerance":0.05},"affichage":"32 kg/m²","explication":"1,75 × 1,75 = 3,0625 ; 98 ÷ 3,0625 ≈ **32,0 kg/m²** : c’est supérieur à 30, donc une obésité."},{"cle":{"type":"zone","ids":["m28","m31","m36"]},"explication":"**Hypertension artérielle**, **apnée du sommeil** et **arthrose** (surtout du genou) sont des conséquences de l’obésité."},{"cle":{"type":"nombre","valeur":29.4,"tolerance":0.05},"affichage":"29,4 kg/m²","explication":"Masse de 90 kg : 90 ÷ 3,0625 ≈ **29,4 kg/m²**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un IMC de 25 à moins de 30 correspond au **surpoids** : Kévin n’est plus en obésité, même s’il lui reste du chemin."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"Le **diététicien** rééquilibre l’alimentation, l’**éducateur sportif** développe l’activité physique, le **psychologue** accompagne, le **médecin** coordonne."}]$ex$::jsonb),
  ('959b38be-a7b5-572a-83d1-df70f9e37c35'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quatre patients, quatre carences à identifier","competence":"raisonner","situation":"Dans un service de nutrition, quatre patients sont suivis pour des signes différents. Chloé, la patiente C, est végétarienne et mange à la cantine du lycée. Tu cherches à chaque fois le déséquilibre en cause.","documents":[{"id":"patients","type":"tableau","titre":"Les signes observés","colonnes":["Patient","Signes observés"],"lignes":[["A","Gencives qui saignent, grande fatigue"],["B","Enfant : os mal minéralisés, jambes arquées"],["C (Chloé, femme)","Fatigue, pâleur, hémoglobine à 9,8 g/dL (seuil : 12 g/dL)"],["D","Amaigrissement extrême avec fonte des muscles"]],"enteteLignes":true,"source":"Patients fictifs"},{"id":"menu","type":"fiche","modele":"menu","entete":"Menu de la cantine","sousTitre":"Mardi","emoji":"🍽️","lignes":[{"texte":"Lentilles vertes et riz","id":"z1"},{"texte":"Pain complet","id":"z2"},{"texte":"Yaourt nature","id":"z3"},{"texte":"Orange","id":"z4"}],"pied":"Menu imaginé pour l’exercice"}],"questions":[{"enonce":"Associe chaque patient à son déséquilibre nutritionnel.","aide":"Gencives qui saignent : vitamine C ; os mous de l’enfant : vitamine D ; pâleur et hémoglobine basse : fer.","type":"association","gauche":[{"id":"g0","texte":"Patient A"},{"id":"g1","texte":"Patient B"},{"id":"g2","texte":"Patient C"},{"id":"g3","texte":"Patient D"}],"droite":[{"id":"d0","texte":"Carence en fer (anémie)"},{"id":"d1","texte":"Carence en vitamine D (rachitisme)"},{"id":"d2","texte":"Apport global insuffisant (cachexie)"},{"id":"d3","texte":"Carence en vitamine C (scorbut)"}]},{"enonce":"De combien l’hémoglobine de Chloé est-elle inférieure au seuil de 12 g/dL ?","aide":"Soustrais 9,8 de 12.","type":"nombre","unite":"g/dL"},{"enonce":"Touche l’aliment du menu qui aide Chloé à absorber le fer des lentilles.","aide":"Une vitamine favorise l’absorption du fer d’origine végétale : où la trouve-t-on dans ce menu ?","type":"zone","document":"menu","multiple":false},{"enonce":"Classe chaque cas : carence quantitative ou carence qualitative ?","aide":"Quantitative : pas assez à manger en tout. Qualitative : assez d’énergie, mais il manque un nutriment précis.","type":"categories","categories":[{"id":"c0","texte":"Quantitative"},{"id":"c1","texte":"Qualitative"}],"items":[{"id":"i0","texte":"Famine"},{"id":"i1","texte":"Anorexie mentale"},{"id":"i2","texte":"Carence en fer"},{"id":"i3","texte":"Carence en vitamine D"},{"id":"i4","texte":"Carence en vitamine C"}]},{"enonce":"Complète avec les bons termes.","aide":"Une racine pour la fonte musculaire, une autre qui signifie « manger beaucoup ».","type":"trous","segments":["L’amaigrissement extrême du patient D s’appelle la ",0,", alors que la ",1," désigne un besoin excessif de manger."],"banque":["cachexie","polyphagie","anorexie","apnée"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"A : **scorbut** (vitamine C). B : **rachitisme** (vitamine D). C : **anémie par carence en fer**. D : **cachexie**, par un apport global insuffisant."},{"cle":{"type":"nombre","valeur":2.2,"tolerance":0.05},"affichage":"2,2 g/dL","explication":"12 − 9,8 = **2,2 g/dL** sous le seuil : cette valeur confirme l’anémie."},{"cle":{"type":"zone","ids":["z4"]},"explication":"L’**orange** apporte de la **vitamine C**, qui favorise l’absorption du fer végétal : un agrume au repas aide."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1"}},"explication":"Famine et anorexie mentale diminuent l’**apport global** (quantitatif). Fer et vitamines C et D sont des **carences ciblées** (qualitatives)."},{"cle":{"type":"trous","trous":[["cachexie"],["polyphagie"]]},"affichage":"cachexie · polyphagie","explication":"La **cachexie** est un amaigrissement extrême avec fonte des muscles ; la **polyphagie** est un besoin excessif de manger. L’**anorexie** est une perte ou un refus de l’appétit."}]$ex$::jsonb),
  ('734017e7-7d24-5609-836b-fdccc5f842a9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le sandwich de Théo, de la bouche au côlon","competence":"observer-schema","situation":"Théo, 16 ans, a mangé un sandwich jambon-beurre à midi. Son professeur lui demande de suivre le trajet du sandwich sur un schéma simplifié, et de repérer les organes qui versent leurs sécrétions sans voir passer les aliments.","documents":[{"id":"schema","type":"schema","titre":"L’appareil digestif (schéma simplifié)","largeur":320,"hauteur":320,"elements":[{"forme":"rect","x":20,"y":15,"l":115,"h":32,"arrondi":8,"teinte":"ambre","motif":"clair","id":"z1","zone":true,"texte":"Bouche"},{"forme":"rect","x":20,"y":57,"l":115,"h":28,"arrondi":8,"teinte":"ambre","motif":"clair","id":"z2","zone":true,"texte":"Œsophage"},{"forme":"rect","x":20,"y":95,"l":115,"h":42,"arrondi":8,"teinte":"ambre","motif":"clair","id":"z3","zone":true,"texte":"Estomac"},{"forme":"rect","x":20,"y":147,"l":115,"h":56,"arrondi":8,"teinte":"ambre","motif":"clair","id":"z4","zone":true,"texte":"Intestin grêle"},{"forme":"rect","x":20,"y":213,"l":115,"h":50,"arrondi":8,"teinte":"ambre","motif":"clair","id":"z5","zone":true,"texte":"Côlon"},{"forme":"rect","x":180,"y":15,"l":120,"h":32,"arrondi":8,"teinte":"turquoise","motif":"clair","id":"z6","zone":true,"texte":"Glandes salivaires"},{"forme":"rect","x":180,"y":105,"l":120,"h":32,"arrondi":8,"teinte":"turquoise","motif":"clair","id":"z7","zone":true,"texte":"Foie"},{"forme":"rect","x":180,"y":170,"l":120,"h":32,"arrondi":8,"teinte":"turquoise","motif":"clair","id":"z8","zone":true,"texte":"Pancréas"},{"forme":"ligne","de":[180,31],"a":[135,31],"fleche":"fin"},{"forme":"ligne","de":[180,121],"a":[135,165],"fleche":"fin"},{"forme":"ligne","de":[180,186],"a":[135,188],"fleche":"fin"},{"forme":"texte","x":160,"y":295,"texte":"Une flèche = une sécrétion déversée dans le tube","taille":"petit","italique":true,"ancre":"milieu"}],"source":"Schéma simplifié, hors échelle"}],"questions":[{"enonce":"Touche l’organe où arrive le sandwich juste après l’œsophage.","aide":"Suis la colonne de gauche de haut en bas : le tube digestif se lit dans l’ordre.","type":"zone","document":"schema","multiple":false},{"enonce":"Touche les trois glandes annexes : aucun aliment ne les traverse.","aide":"Ce sont les organes qui ont une flèche : ils envoient leurs sécrétions vers le tube.","type":"zone","document":"schema","multiple":true},{"enonce":"Associe chaque racine médicale à l’organe qu’elle désigne.","aide":"Une gastrite touche l’estomac ; une hépatite touche un autre organe annexe.","type":"association","gauche":[{"id":"g0","texte":"gastr(o)"},{"id":"g1","texte":"hépat(o)"},{"id":"g2","texte":"entér(o)"},{"id":"g3","texte":"stomat(o)"}],"droite":[{"id":"d0","texte":"Bouche"},{"id":"d1","texte":"Estomac"},{"id":"d2","texte":"Intestin"},{"id":"d3","texte":"Foie"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Après l’œsophage, les aliments arrivent dans **l’estomac**, où ils sont brassés et mélangés au suc gastrique."},{"cle":{"type":"zone","ids":["z6","z7","z8"]},"explication":"Les **glandes salivaires, le foie et le pancréas** sont les glandes annexes : elles déversent salive, bile et suc pancréatique dans le tube digestif sans être traversées par les aliments."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"**gastr(o)** : estomac ; **hépat(o)** : foie ; **entér(o)** : intestin ; **stomat(o)** : bouche. Ces racines se combinent avec des suffixes pour former les mots médicaux."}]$ex$::jsonb),
  ('734017e7-7d24-5609-836b-fdccc5f842a9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les cinq tubes à essais de Nora","competence":"experimenter","situation":"Au lycée, Nora prépare cinq tubes contenant de l’amidon, puis les place 30 minutes dans des conditions différentes. Elle recherche ensuite l’amidon et le maltose dans chaque tube. Le tableau donne ses résultats.","documents":[{"id":"tubes","type":"tableau","titre":"Résultats de l’expérience sur l’amylase salivaire","colonnes":["Tube","Contenu et conditions","Amidon après 30 min","Maltose après 30 min"],"lignes":[["A","Amidon + salive, 37 °C, pH 7","absent","présent"],["B","Amidon + salive, 0 °C","présent","absent"],["C","Amidon + salive chauffée à 100 °C puis refroidie à 37 °C","présent","absent"],["D","Amidon + salive, 37 °C, pH 2","présent","absent"],["E","Amidon + eau (pas de salive), 37 °C","présent","absent"]],"enteteLignes":true,"source":"Expérience décrite pour l’exercice"}],"questions":[{"enonce":"Touche la case qui montre que l’amidon a disparu dans un tube.","aide":"Regarde la colonne « Amidon » : cherche la seule case où il n’y en a plus.","type":"zone","document":"tubes","multiple":false},{"enonce":"À quoi sert le tube E, où la salive est remplacée par de l’eau ?","aide":"Un tube témoin est identique aux autres, sauf pour le facteur qu’on teste : ici, la salive.","type":"choix","options":[{"id":"a","texte":"À montrer que l’amidon ne disparaît pas sans enzyme"},{"id":"b","texte":"À montrer que l’eau digère l’amidon à 37 °C"},{"id":"c","texte":"À fabriquer davantage de maltose dans le tube"},{"id":"d","texte":"À prouver que la salive contient de l’amidon"}],"multiple":false},{"enonce":"Que montrent ensemble les tubes B, C et D ?","aide":"Dans ces trois tubes, la salive est là, mais l’amidon n’est pas digéré. Qu’est-ce qui a changé ?","type":"choix","options":[{"id":"a","texte":"Chauffer la salive à 100 °C renforce l’action de l’amylase"},{"id":"b","texte":"Un pH de 2 accélère la digestion de l’amidon dans le tube"},{"id":"c","texte":"L’enzyme n’agit bien qu’à une température et un pH adaptés"},{"id":"d","texte":"L’amylase digère l’amidon même à 0 °C si on attend longtemps"}],"multiple":false},{"enonce":"Les enzymes sont spécifiques. Associe chaque enzyme à son substrat.","aide":"Le nom de l’enzyme rappelle souvent celui du substrat : la maltase agit sur le maltose.","type":"association","gauche":[{"id":"g0","texte":"Amylase"},{"id":"g1","texte":"Pepsine"},{"id":"g2","texte":"Lipase"},{"id":"g3","texte":"Maltase"}],"droite":[{"id":"d0","texte":"Amidon"},{"id":"d1","texte":"Protéines"},{"id":"d2","texte":"Maltose"},{"id":"d3","texte":"Triglycérides"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"Seul le tube A ne contient plus d’amidon : **absent**. Il contient du maltose : l’amidon a été digéré en maltose par l’amylase."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le tube E est le **témoin** : sans salive, donc sans amylase, l’amidon reste présent et aucun maltose n’apparaît. C’est bien la salive qui digère l’amidon."},{"cle":{"type":"choix","ids":["c"]},"explication":"Dans B, C et D, l’amidon n’est pas digéré malgré la salive : **l’enzyme a besoin d’une température optimale (37 °C) et d’un pH optimal** pour agir."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"**Amylase → amidon ; pepsine → protéines ; lipase → triglycérides ; maltase → maltose**. Chaque enzyme n’hydrolyse qu’un substrat précis : c’est la spécificité."}]$ex$::jsonb),
  ('734017e7-7d24-5609-836b-fdccc5f842a9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Des selles grasses et un pancréas atrophié","competence":"analyser-document","situation":"M. Lemoine, 58 ans, a maigri et ses selles sont grasses. Le laboratoire a dosé les enzymes de son duodénum, et un scanner a examiné son pancréas. Le deuxième document rappelle comment on digère les graisses.","documents":[{"id":"labo","type":"fiche","modele":"ticket","titre":"Résultats de M. Lemoine","entete":"Laboratoire — résultats","sousTitre":"M. Lemoine, 58 ans","emoji":"🧪","lignes":[{"texte":"Signes","valeur":"selles grasses","id":"z1"},{"separateur":true},{"texte":"Bile","valeur":"normale","id":"z2"},{"texte":"Lipase","valeur":"8 % de la normale","id":"z3"},{"texte":"Scanner pancréas","valeur":"atrophie","id":"z4"}],"pied":"Document écrit pour l’exercice"},{"id":"graisses","type":"chaine","disposition":"ligne","titre":"La digestion des graisses","noeuds":[{"id":"z5","texte":"Triglycérides","emoji":"🧈"},{"id":"z6","texte":"Fines gouttelettes","emoji":"💧"},{"id":"z7","texte":"Acides gras + monoglycérides","emoji":"🔬"}],"liens":[{"de":"z5","a":"z6","texte":"bile"},{"de":"z6","a":"z7","texte":"lipase"}]}],"questions":[{"enonce":"Touche la ligne qui montre quelle enzyme digestive fait défaut.","aide":"La bile n’est pas une enzyme : cherche un nom qui se termine en « -ase ».","type":"zone","document":"labo","multiple":false},{"enonce":"Touche ce que la bile fabrique à partir des triglycérides.","aide":"La bile n’hydrolyse pas : elle découpe les graisses en toutes petites parties.","type":"zone","document":"graisses","multiple":false},{"enonce":"Pourquoi les graisses ne sont-elles pas digérées alors que la bile est normale ?","aide":"Regarde la chaîne : la bile prépare le travail, mais qui hydrolyse les triglycérides ?","type":"choix","options":[{"id":"a","texte":"Sans lipase, le foie cesse de fabriquer la bile"},{"id":"b","texte":"Les gouttelettes ne sont pas hydrolysées sans lipase"},{"id":"c","texte":"Le scanner montre que la vésicule biliaire est enlevée"},{"id":"d","texte":"La bile détruit la lipase dès son arrivée dans le duodénum"}],"multiple":false},{"enonce":"Classe chaque élément selon son rôle dans la digestion.","aide":"Une enzyme est une protéine qui coupe un substrat ; les autres fragmentent ou émulsionnent.","type":"categories","categories":[{"id":"c0","texte":"Enzyme qui hydrolyse"},{"id":"c1","texte":"Augmente la surface d’action"}],"items":[{"id":"i0","texte":"Mastication"},{"id":"i1","texte":"Trypsine"},{"id":"i2","texte":"Lipase"},{"id":"i3","texte":"Bile"},{"id":"i4","texte":"Brassage de l’estomac"},{"id":"i5","texte":"Pepsine"}]},{"enonce":"Quel traitement est cohérent avec le mécanisme de la maladie de M. Lemoine ?","aide":"Justifier un traitement, c’est montrer qu’il corrige ce qui manque ou ce qui dysfonctionne.","type":"choix","options":[{"id":"a","texte":"Des enzymes pancréatiques prises pendant les repas"},{"id":"b","texte":"Un bronchodilatateur inhalé de courte durée"},{"id":"c","texte":"Un régime strict sans gluten à vie, sans exception"},{"id":"d","texte":"Une ablation de la vésicule biliaire en urgence"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La **lipase** du suc duodénal est tombée à 8 % de la normale : le pancréas ne produit presque plus cette enzyme."},{"cle":{"type":"zone","ids":["z6"]},"explication":"Les sels biliaires **émulsionnent** les graisses en **fines gouttelettes**, ce qui augmente la surface sur laquelle la lipase peut agir."},{"cle":{"type":"choix","ids":["b"]},"explication":"La bile émulsionne, mais seule la **lipase** hydrolyse les triglycérides. Sans elle, les gouttelettes restent intactes et les graisses sont éliminées dans les selles."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c1","i5":"c0"}},"explication":"**Lipase, trypsine, pepsine** sont des enzymes. **Bile, mastication, brassage** fragmentent les aliments ou les graisses : ils augmentent la surface offerte aux enzymes."},{"cle":{"type":"choix","ids":["a"]},"explication":"Il manque la lipase : on **remplace les enzymes pancréatiques** au moment des repas, ce qui rétablit la digestion des graisses."}]$ex$::jsonb),
  ('de7f6cd7-d785-5092-8ca2-b810b3237f5f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Deux vaisseaux dans une villosité","competence":"observer-schema","situation":"Pour son exposé, Ambre dessine une villosité de l’intestin grêle : un repli de la muqueuse d’environ 1 mm. Elle y place les deux vaisseaux par lesquels les nutriments rejoignent la circulation.","documents":[{"id":"villo","type":"schema","titre":"Coupe d’une villosité intestinale","largeur":320,"hauteur":300,"elements":[{"forme":"rect","x":95,"y":20,"l":130,"h":230,"arrondi":60,"teinte":"ambre","motif":"clair","id":"z1"},{"forme":"rect","x":112,"y":75,"l":26,"h":150,"arrondi":13,"teinte":"corail","motif":"plein","id":"z2","zone":true},{"forme":"rect","x":150,"y":60,"l":26,"h":165,"arrondi":13,"teinte":"jaune","motif":"plein","id":"z3","zone":true},{"forme":"texte","x":88,"y":146,"texte":"Capillaire","taille":"petit","ancre":"fin"},{"forme":"texte","x":88,"y":160,"texte":"sanguin","taille":"petit","ancre":"fin"},{"forme":"ligne","de":[91,153],"a":[112,153],"fleche":"fin"},{"forme":"texte","x":232,"y":138,"texte":"Vaisseau","taille":"petit","ancre":"debut"},{"forme":"texte","x":232,"y":152,"texte":"lymphatique","taille":"petit","ancre":"debut"},{"forme":"ligne","de":[229,146],"a":[179,146],"fleche":"fin"},{"forme":"texte","x":232,"y":60,"texte":"Entérocytes","taille":"petit","ancre":"debut"},{"forme":"ligne","de":[229,56],"a":[215,56],"fleche":"fin"},{"forme":"texte","x":160,"y":280,"texte":"Lumière de l’intestin (aliments digérés)","taille":"petit","italique":true,"ancre":"milieu"}],"source":"Schéma simplifié, hors échelle"}],"questions":[{"enonce":"Touche le vaisseau qui emporte le glucose absorbé vers la veine porte.","aide":"Le glucose est une molécule hydrophile : elle passe directement dans le sang.","type":"zone","document":"villo","multiple":false},{"enonce":"Touche le vaisseau qui emporte les chylomicrons, chargés de graisses.","aide":"Les graisses ne voyagent pas librement dans le sang : elles prennent une autre voie.","type":"zone","document":"villo","multiple":false},{"enonce":"Complète le trajet du glucose après son absorption.","aide":"La voie sanguine passe par un vaisseau « porte » avant de rejoindre un organe qui trie les nutriments.","type":"trous","segments":["Les capillaires de la villosité rejoignent la ",0," qui conduit le sang vers le ",1,"."],"banque":["cœur","foie","veine porte","veine cave","poumon"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le glucose gagne **le capillaire sanguin**, puis la veine porte qui le conduit au foie."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Les triglycérides emballés en chylomicrons passent dans **le chylifère**, vaisseau lymphatique central de la villosité, avant de rejoindre le sang."},{"cle":{"type":"trous","trous":[["veine porte"],["foie"]]},"affichage":"veine porte · foie","explication":"Les capillaires intestinaux se jettent dans **la veine porte**, qui conduit le sang vers **le foie**."}]$ex$::jsonb),
  ('de7f6cd7-d785-5092-8ca2-b810b3237f5f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La fibroscopie de M. Garnier","competence":"analyser-document","situation":"M. Garnier, 52 ans, a vomi du sang. Le gastro-entérologue lui a fait une fibroscopie pour examiner son tube digestif supérieur. Voici le compte rendu de l’examen.","documents":[{"id":"cr","type":"fiche","modele":"ticket","titre":"Compte rendu de la fibroscopie","entete":"Compte rendu de fibroscopie","sousTitre":"M. Garnier, 52 ans","emoji":"🩺","lignes":[{"texte":"Motif","valeur":"hématémèse","id":"z1"},{"separateur":true},{"texte":"Œsophage","valeur":"muqueuse normale","id":"z2"},{"texte":"Estomac","valeur":"ulcère de 1 cm","id":"z3"},{"texte":"Duodénum","valeur":"muqueuse normale","id":"z4"},{"separateur":true},{"texte":"Prélèvements","valeur":"4 biopsies","id":"z5"}],"pied":"Compte rendu écrit pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui décrit une perte de substance de la muqueuse.","aide":"Cherche le mot qui désigne une lésion de la muqueuse, pas une zone « normale ».","type":"zone","document":"cr","multiple":false},{"enonce":"Associe chaque terme à sa définition.","aide":"Le préfixe « hémat- » renvoie au sang ; « -émèse » au vomissement.","type":"association","gauche":[{"id":"g0","texte":"Hématémèse"},{"id":"g1","texte":"Rectorragie"},{"id":"g2","texte":"Polype"},{"id":"g3","texte":"Ulcère"}],"droite":[{"id":"d0","texte":"Excroissance de la muqueuse"},{"id":"d1","texte":"Vomissement de sang"},{"id":"d2","texte":"Perte de substance de la muqueuse"},{"id":"d3","texte":"Saignement par l’anus"}]},{"enonce":"Dans quel ordre le tube souple de la fibroscopie traverse-t-il le corps de M. Garnier ?","aide":"Le tube suit le trajet des aliments, de l’entrée jusqu’au début de l’intestin grêle.","type":"ordre","items":[{"id":"a","texte":"Duodénum"},{"id":"b","texte":"Estomac"},{"id":"c","texte":"Bouche"},{"id":"d","texte":"Œsophage"},{"id":"e","texte":"Pharynx"}]},{"enonce":"Pour explorer le côlon de M. Garnier, par où faudrait-il introduire le tube ?","aide":"Il faut rejoindre le côlon par l’extrémité du tube digestif la plus proche de lui.","type":"choix","options":[{"id":"a","texte":"Par une petite incision de la peau du ventre"},{"id":"b","texte":"Par l’anus, pour une coloscopie"},{"id":"c","texte":"Par la bouche, comme pour son estomac"},{"id":"d","texte":"Par le nez, au niveau des fosses nasales"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Un **ulcère** est une perte de substance de la muqueuse : il siège ici dans l’estomac."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"**Hématémèse** : vomissement de sang ; **rectorragie** : saignement par l’anus ; **polype** : excroissance de la muqueuse ; **ulcère** : perte de substance de la muqueuse."},{"cle":{"type":"ordre","ids":["c","e","d","b","a"]},"explication":"Par la bouche : **bouche → pharynx → œsophage → estomac → duodénum**. C’est une fibroscopie œso-gastro-duodénale."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le côlon s’explore **par l’anus** : c’est la coloscopie. La fibroscopie œso-gastro-duodénale, elle, passe par la bouche."}]$ex$::jsonb),
  ('de7f6cd7-d785-5092-8ca2-b810b3237f5f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Lina, 6 ans, ne grandit plus","competence":"raisonner","situation":"Lina, 6 ans, a souvent la diarrhée, le ventre ballonné et ne grandit plus comme les autres enfants. Son médecin a prescrit un bilan sanguin et une fibroscopie avec biopsie du duodénum. Les résultats arrivent.","documents":[{"id":"bilan","type":"tableau","titre":"Bilan de Lina","colonnes":["Examen","Résultat de Lina","Valeur de référence"],"lignes":[["Hémoglobine","9,5 g/dL","11,5 à 13,5 g/dL"],["Anticorps spécifiques du gluten","présents","absents"],["Biopsie du duodénum","atrophie des villosités","villosités normales"]],"enteteLignes":true,"source":"Valeurs arrondies, bilan écrit pour l’exercice"},{"id":"menu","type":"fiche","modele":"menu","titre":"Menu de la cantine","entete":"Menu de la cantine","sousTitre":"Jeudi","emoji":"🍽️","lignes":[{"texte":"Salade de riz","id":"z1"},{"texte":"Pâtes au blé","id":"z2"},{"texte":"Pain de seigle","id":"z3"},{"texte":"Pommes de terre vapeur","id":"z4"},{"texte":"Soupe d’orge perlé","id":"z5"},{"texte":"Yaourt nature","id":"z6"}],"pied":"Menu écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui montre la lésion de l’intestin de Lina.","aide":"La lésion concerne les villosités : elle se voit sur un prélèvement du duodénum.","type":"zone","document":"bilan","multiple":false},{"enonce":"De combien de g/dL son hémoglobine est-elle sous la limite basse de la valeur de référence ?","aide":"Soustrais son résultat à la plus petite valeur de référence (11,5).","type":"nombre","unite":"g/dL"},{"enonce":"Classe chaque élément du dossier de Lina.","aide":"Le signe clinique se constate chez le patient ; le paraclinique vient d’un examen complémentaire.","type":"categories","categories":[{"id":"c0","texte":"Signe clinique"},{"id":"c1","texte":"Signe paraclinique"}],"items":[{"id":"i0","texte":"Anticorps dans le sang"},{"id":"i1","texte":"Diarrhée chronique"},{"id":"i2","texte":"Biopsie du duodénum"},{"id":"i3","texte":"Retard de croissance"},{"id":"i4","texte":"Hémoglobine basse"},{"id":"i5","texte":"Ballonnements"}]},{"enonce":"Remets dans l’ordre le mécanisme qui mène aux signes de Lina.","aide":"Pars de la cause (le gluten) et termine par les signes que l’on observe.","type":"ordre","items":[{"id":"a","texte":"Les villosités du duodénum s’atrophient"},{"id":"b","texte":"Le gluten déclenche une réaction immunitaire"},{"id":"c","texte":"La surface d’absorption s’effondre"},{"id":"d","texte":"Les nutriments et le fer ne sont plus absorbés"},{"id":"e","texte":"Diarrhée, anémie et retard de croissance"}]},{"enonce":"Touche les trois plats que Lina devra éviter : ils contiennent du gluten.","aide":"Le gluten est une protéine de trois céréales : le blé, l’orge et le seigle.","type":"zone","document":"menu","multiple":true}]}$ex$::jsonb,
