":[{"enonce":"Touche la cavité qui reçoit le sang riche en dioxygène venant des poumons.","aide":"Le sang des poumons revient par les veines pulmonaires : suis la flèche.","type":"zone","document":"coeur","multiple":false},{"enonce":"Touche la cavité qui envoie le sang dans l’aorte, vers tout le corps.","aide":"Cherche d’où part la flèche « Aorte ».","type":"zone","document":"coeur","multiple":false},{"enonce":"Calcule le volume d’éjection systolique (VES) de Salomé.","aide":"VES = volume en fin de diastole − volume en fin de systole.","type":"nombre","unite":"mL"}]}$ex$::jsonb,
