   $ex${"titre":"Le trajet de l’air de Kévin","competence":"observer-schema","situation":"Kévin court tous les matins. Pour comprendre où va l’air qu’il respire, sa sœur lui montre un schéma simplifié de l’appareil respiratoire.","documents":[{"id":"resp","type":"schema","titre":"L’appareil respiratoire (schéma simplifié)","largeur":320,"hauteur":310,"elements":[{"forme":"ellipse","cx":90,"cy":215,"rx":55,"ry":80,"teinte":"ciel","motif":"clair"},{"forme":"ellipse","cx":230,"cy":215,"rx":55,"ry":80,"teinte":"ciel","motif":"clair"},{"forme":"ellipse","cx":160,"cy":22,"rx":28,"ry":14,"teinte":"turquoise","motif":"clair","id":"z1","zone":true},{"forme":"rect","x":140,"y":42,"l":40,"h":20,"arrondi":6,"teinte":"turquoise","motif":"clair","id":"z2","zone":true},{"forme":"rect","x":142,"y":66,"l":36,"h":22,"arrondi":6,"teinte":"turquoise","motif":"clair","id":"z3","zone":true},{"forme":"rect","x":146,"y":92,"l":28,"h":60,"arrondi":6,"teinte":"turquoise","motif":"clair","id":"z4","zone":true},{"forme":"ligne","de":[160,152],"a":[115,195]},{"forme":"ligne","de":[160,152],"a":[205,195]},{"forme":"cercle","cx":70,"cy":240,"r":15,"teinte":"rose","motif":"plein","id":"z5","zone":true},{"forme":"texte","x":118,"y":26,"texte":"Fosses nasales","taille":"petit","ancre":"fin"},{"forme":"texte","x":134,"y":56,"texte":"Pharynx","taille":"petit","ancre":"fin"},{"forme":"texte","x":136,"y":82,"texte":"Larynx","taille":"petit","ancre":"fin"},{"forme":"texte","x":140,"y":126,"texte":"Trachée","taille":"petit","ancre":"fin"},{"forme":"texte","x":180,"y":148,"texte":"Bronches","taille":"petit","ancre":"debut"},{"forme":"texte","x":230,"y":305,"texte":"Poumons","taille":"petit","ancre":"milieu"},{"forme":"texte","x":70,"y":275,"texte":"Alvéole","taille":"petit","ancre":"milieu"},{"forme":"texte","x":70,"y":289,"texte":"(agrandie)","taille":"petit","italique":true,"ancre":"milieu"}],"source":"Schéma simplifié, hors échelle"}],"questions":[{"enonce":"Touche l’organe situé juste sous le larynx.","aide":"Suis le trajet de l’air de haut en bas, après le larynx.","type":"zone","document":"resp","multiple":false},{"enonce":"Touche la structure où le dioxygène passe de l’air vers le sang.","aide":"C’est tout au bout du trajet : un petit sac entouré de capillaires.","type":"zone","document":"resp","multiple":false},{"enonce":"Associe chaque structure à son rôle.","aide":"Les bronchioles n’ont pas de cartilage : leur paroi contient un autre tissu.","type":"association","gauche":[{"id":"g0","texte":"Trachée"},{"id":"g1","texte":"Cils de l’épithélium"},{"id":"g2","texte":"Bronchioles"},{"id":"g3","texte":"Alvéoles"}],"droite":[{"id":"d0","texte":"Règlent le passage de l’air avec leur muscle lisse"},{"id":"d1","texte":"Reste ouverte grâce à ses anneaux de cartilage"},{"id":"d2","texte":"Siège des échanges gazeux"},{"id":"d3","texte":"Remontent le mucus chargé de particules"}]}]}$ex$::jsonb,
