  ('80f01940-fb6e-5480-adf0-622d44c0886d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les gaz du sang à l’entrée des poumons","competence":"lire-tableau","situation":"Inès, étudiante infirmière, doit expliquer à un patient dans quel sens le dioxygène et le dioxyde de carbone passent dans les poumons. Elle s’appuie sur un tableau de pressions partielles et sur la répartition du CO₂ dans le sang.","documents":[{"id":"pressions","type":"tableau","titre":"Pressions partielles (mmHg)","colonnes":["Milieu","O₂","CO₂"],"lignes":[["Air des alvéoles",100,40],["Sang arrivant aux poumons",40,46]],"enteteLignes":true,"source":"Valeurs arrondies"},{"id":"co2","type":"graphique","forme":"secteurs","titre":"Formes de transport du CO₂ dans le sang","categories":["Ions hydrogénocarbonate","Carbaminohémoglobine","CO₂ dissous"],"series":[{"nom":"Part du CO₂ transporté (%)","valeurs":[70,20,10],"teinte":"violet"}],"source":"Valeurs arrondies"}],"questions":[{"enonce":"De combien de mmHg la pression partielle de O₂ de l’air des alvéoles dépasse-t-elle celle du sang arrivant aux poumons ?","aide":"Soustrais la plus petite pression de O₂ à la plus grande.","type":"nombre","unite":"mmHg"},{"enonce":"Dans quel sens le CO₂ diffuse-t-il au niveau des alvéoles ?","aide":"Un gaz diffuse du milieu où sa pression partielle est la plus forte vers celui où elle est la plus faible.","type":"choix","options":[{"id":"a","texte":"De l’air des alvéoles vers le sang, car 40 est inférieur à 46"},{"id":"b","texte":"Du sang vers l’air des alvéoles, car 46 est inférieur à 100"},{"id":"c","texte":"Du sang vers l’air des alvéoles, car 46 est supérieur à 40"},{"id":"d","texte":"Il ne diffuse pas : les deux pressions sont trop proches"}],"multiple":false},{"enonce":"Touche la forme de transport majoritaire du CO₂.","aide":"Cherche le plus grand secteur.","type":"zone","document":"co2","multiple":false},{"enonce":"Quel pourcentage du CO₂ n’est pas transporté sous forme d’hydrogénocarbonate ?","aide":"Additionne les deux autres formes de transport.","type":"nombre","unite":"%"}]}$e