  ('22aad1df-1f4d-53c7-8d43-3f7d86b4a815'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux souffles, deux rapports de Tiffeneau","competence":"calculer","situation":"Hugo, 30 ans, sert de témoin. Lina, 17 ans, siffle depuis plusieurs semaines. Le pneumologue mesure leur capacité vitale (CV) et leur VEMS, puis refait la mesure de Lina après un bronchodilatateur.","documents":[{"id":"mesures","type":"tableau","titre":"Mesures de spirométrie","colonnes":["Mesure","Hugo (témoin)","Lina avant","Lina après bronchodilatateur"],"lignes":[["CV (L)","4,5","4,0","4,0"],["VEMS (L)","3,6","2,4","3,4"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Calcule le rapport de Tiffeneau de Lina avant le médicament (VEMS ÷ CV), en pourcentage.","aide":"Divise le VEMS de Lina par sa capacité vitale, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Que dit ce rapport de Lina avant le médicament ?","aide":"Compare avec la limite d’environ 70 %.","type":"choix","options":[{"id":"a","texte":"Il prouve que son volume résiduel est trop élevé"},{"id":"b","texte":"Il est supérieur à 70 % : poumons parfaitement normaux"},{"id":"c","texte":"Il est égal à celui de Hugo, qui vaut 80 %"},{"id":"d","texte":"Il est inférieur à 70 % : trouble ventilatoire obstructif"}],"multiple":false},{"enonce":"Calcule le rapport de Tiffeneau de Lina après le bronchodilatateur, en pourcentage.","aide":"Même calcul, avec le VEMS après le médicament.","type":"nombre","unite":"%"},{"enonce":"Que montre le retour du rapport à 85 % après le médicament ?","aide":"Dans l’asthme l’obstruction s’efface après le bronchodilatateur, dans la BPCO elle reste.","type":"choix","options":[{"id":"a","texte":"Les bronches sont détruites par le tabac depuis longtemps"},{"id":"b","texte":"Le médicament a augmenté la capacité vitale de 2 litres"},{"id":"c","texte":"L’obstruction est définitive : cela évoque une BPCO"},{"id":"d","texte":"L’obstruction est réversible : cela évoque un asthme"}],"multiple":false}]}$ex$::jsonb,
