  ('9986c725-731a-5c56-b904-c4905832ba57'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le yaourt sans lactose de l’équipe de Zoé","competence":"experimenter","situation":"Zoé et son groupe veulent produire un yaourt sans lactose. Leur hypothèse : une lactase ajoutée au lait avant la fermentation transforme le lactose en glucose. Ils testent trois tubes avec une bandelette qui détecte le glucose.","documents":[{"id":"tubes","type":"tableau","titre":"Les trois tubes de l’équipe","colonnes":["Tube","Contenu","Bandelette glucose"],"lignes":[["A","Lait + lactase, 30 min à 37 °C","positive"],["B","Lait seul, 30 min à 37 °C","négative"],["C","Solution de glucose à 1 g·L⁻¹","positive"]],"enteteLignes":true,"source":"Résultats écrits pour l’exercice"}],"questions":[{"enonce":"Touche le tube qui joue le rôle de témoin positif de la bandelette.","aide":"Un témoin positif doit réagir à coup sûr : quel tube contient du glucose dès le départ ?","type":"zone","document":"tubes","multiple":false},{"enonce":"Que prouve le résultat négatif du tube B ?","aide":"Compare A et B : un seul facteur change entre les deux tubes.","type":"choix","options":[{"id":"a","texte":"Le lait contient déjà tout le glucose avant l’expérience"},{"id":"b","texte":"La bandelette ne sait pas détecter le glucose dans le lait"},{"id":"c","texte":"La lactase est inefficace dans le lait à 37 °C pendant 30 min"},{"id":"d","texte":"Le lait seul ne donne pas de glucose, donc il vient de la lactase"}],"multiple":false},{"enonce":"Remets dans l’ordre les étapes de la démarche de l’équipe.","aide":"On commence par un besoin, on termine par la communication des résultats.","type":"ordre","items":[{"id":"a","texte":"Partir du besoin : un yaourt pour les intolérants au lactose"},{"id":"b","texte":"Émettre l’hypothèse : la lactase hydrolyse le lactose"},{"id":"c","texte":"Conclure et rendre compte à l’écrit"},{"id":"d","texte":"Réaliser les tubes et lire les bandelettes"},{"id":"e","texte":"Prévoir les tubes avec leurs témoins"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Le tube **C** contient du glucose : la bandelette doit y réagir. S’il avait été négatif, la bandelette serait en cause."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le tube B est le **témoin négatif** : mêmes conditions que A, sauf la lactase. Comme il ne réagit pas, le glucose du tube A vient bien de la lactase."},{"cle":{"type":"ordre","ids":["a","b","e","d","c"]},"explication":"Besoin, **hypothèse**, expérience avec **témoins**, mise en œuvre, puis exploitation et compte rendu : c’est la démarche expérimentale."}]$ex$::jsonb),
  ('9986c725-731a-5c56-b904-c4905832ba57'::uuid, 3, 3, 15, 50, 3,
   $ex${"titre":"Blog ou revue : à qui se fier ?","competence":"argumenter","situation":"Pour son dossier sur les brevets du vivant, Enzo a trouvé trois sources. Avant de les citer dans sa sitographie, son groupe doit juger leur fiabilité, puis séparer les arguments des opinions.","documents":[{"id":"sources","type":"tableau","titre":"Les trois sources d’Enzo","colonnes":["Source","Auteur","Date","Références"],"lignes":[["Blog « Vivant Libre »","anonyme","non datée","aucune"],["Article d’une revue scientifique","équipe d’un laboratoire, nommée","2024","14 références"],["Forum de discussion","pseudonyme","2021","aucune"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la source qu’Enzo peut citer en priorité.","aide":"Vérifie l’auteur, la date et les références.","type":"zone","document":"sources","multiple":false},{"enonce":"Classe ces phrases : argument appuyé sur des sources ou simple opinion ?","aide":"Un argument renvoie à un fait vérifiable ou à une source ; une opinion exprime un ressenti.","type":"categories","categories":[{"id":"c0","texte":"Argument appuyé sur des sources"},{"id":"c1","texte":"Opinion"}],"items":[{"id":"i0","texte":"Modifier le vivant, c’est jouer à Dieu"},{"id":"i1","texte":"Moi, je trouve ça dégoûtant"},{"id":"i2","texte":"Selon l’article de 2024, 80 % des essais ont été validés"},{"id":"i3","texte":"Les données du tableau 2 montrent une baisse du risque"},{"id":"i4","texte":"La loi encadre cette technique, voir le texte cité en référence 9"}]},{"enonce":"Relie chaque outil numérique à son usage au laboratoire.","aide":"Pense à ce que chaque outil permet de produire ou de chercher.","type":"association","gauche":[{"id":"g0","texte":"Tableur-grapheur"},{"id":"g1","texte":"Base de données"},{"id":"g2","texte":"Logiciel de visualisation 3D"},{"id":"g3","texte":"Outil collaboratif"}],"droite":[{"id":"d0","texte":"Tracer une courbe d’étalonnage"},{"id":"d1","texte":"Observer une protéine dans l’espace"},{"id":"d2","texte":"Co-écrire un compte rendu"},{"id":"d3","texte":"Chercher une séquence par mots clés"}]}]}$ex$::jsonb,
