  ('ebe4cc3f-16ca-589c-9139-325f7df474fa'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’étiquette du flacon de soude","competence":"analyser-document","situation":"En début de TP, Malik doit préparer une solution à partir d’un flacon de soude. Avant d’y toucher, il lit l’étiquette.","documents":[{"id":"etiquette","type":"fiche","modele":"etiquette","titre":"Étiquette du flacon","entete":"Hydroxyde de sodium","sousTitre":"Solution à 2 mol·L⁻¹ (soude)","emoji":"🧴","lignes":[{"texte":"Mention d’avertissement","valeur":"DANGER","gras":true,"id":"z1"},{"texte":"H314 : provoque de graves brûlures de la peau et de graves lésions des yeux","id":"z2"},{"separateur":true},{"texte":"P280 : porter des gants et une protection des yeux","id":"z3"}],"pied":"Étiquette écrite pour l’exercice","teinte":"corail"}],"questions":[{"enonce":"Touche la mention d’avertissement.","aide":"C’est un seul mot, en majuscules, qui indique la gravité.","type":"zone","document":"etiquette","multiple":false},{"enonce":"Touche la ligne qui est un conseil de prudence (phrase P).","aide":"Les conseils de prudence commencent par la lettre P et disent quoi faire.","type":"zone","document":"etiquette","multiple":false},{"enonce":"Avec l’exemple de la soude, relie chaque terme à sa situation.","aide":"Suis l’ordre : propriété, contact, déclenchement, lésion.","type":"association","gauche":[{"id":"g0","texte":"Danger"},{"id":"g1","texte":"Situation exposante"},{"id":"g2","texte":"Événement dangereux"},{"id":"g3","texte":"Dommage"}],"droite":[{"id":"d0","texte":"Une projection dans l’œil"},{"id":"d1","texte":"Brûlure de l’œil"},{"id":"d2","texte":"Verser la soude sans lunettes"},{"id":"d3","texte":"La soude est corrosive"}]}]}$ex$::jsonb,
