  ('ebe4cc3f-16ca-589c-9139-325f7df474fa'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ensemencer une gélose sans se mettre en danger","competence":"analyser-document","situation":"Léa doit ensemencer une gélose à partir d’une culture d’*Escherichia coli* K12 (groupe de risque 1). Son professeur lui demande de représenter la chaîne de transmission, puis de classer les étapes du TP selon leur risque.","documents":[{"id":"chaine","type":"chaine","disposition":"colonne","noeuds":[{"id":"z1","texte":"Culture dans le tube","emoji":"🧫"},{"id":"z2","texte":"Aérosol à l’ouverture du tube"},{"id":"z3","texte":"Air de la paillasse"},{"id":"z4","texte":"Voie respiratoire"},{"id":"z5","texte":"Manipulateur","emoji":"🧑‍🔬"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]},{"id":"risques","type":"tableau","titre":"Étapes du TP (probabilité et gravité notées de 1 à 4)","colonnes":["Étape","Probabilité","Gravité"],"lignes":[["Ouvrir le tube de culture",3,2],["Verser de l’éthanol près de la flamme",2,4],["Jeter les boîtes en DASRI",1,2]],"enteteLignes":true,"source":"Échelle écrite pour l’exercice"}],"questions":[{"enonce":"Touche le maillon qui est le réservoir de micro-organismes.","aide":"Le réservoir est l’endroit où vivent et se multiplient les micro-organismes.","type":"zone","document":"chaine","multiple":false},{"enonce":"Relie chaque voie d’exposition à un exemple de laboratoire.","aide":"Contact : peau, œil. Inhalation : on respire. Ingestion : on avale.","type":"association","gauche":[{"id":"g0","texte":"Contact"},{"id":"g1","texte":"Inhalation"},{"id":"g2","texte":"Ingestion"}],"droite":[{"id":"d0","texte":"Aérosol à l’ensemencement"},{"id":"d1","texte":"Pipetage à la bouche"},{"id":"d2","texte":"Projection sur la peau"}]},{"enonce":"Le score de risque est probabilité × gravité. Dans le tableau, quel est le score de l’étape « Ouvrir le tube de culture » ?","aide":"Multiplie les deux nombres de la ligne.","type":"nombre"},{"enonce":"Touche l’étape dont le score de risque est le plus élevé.","aide":"Calcule le score de chacune des trois lignes avant de comparer.","type":"zone","document":"risques","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le **réservoir** est la culture dans le tube. Ensuite viennent la voie de sortie (l’aérosol), le mode de transmission (l’air), la voie d’entrée et la personne exposée."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"La projection touche la peau (**contact**), l’aérosol se respire (**inhalation**) et le pipetage à la bouche (interdit !) fait avaler (**ingestion**)."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"3 × 2 = **6** : le risque combine la probabilité du dommage et sa gravité."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Scores : 3 × 2 = 6, 2 × 4 = **8**, 1 × 2 = 2. L’éthanol près de la flamme domine : même peu probable, son dommage est grave."}]$ex$::jsonb),
  ('ebe4cc3f-16ca-589c-9139-325f7df474fa'::uuid, 3, 3, 15, 50, 4,
