  ('fe03ae69-9ff2-5a5c-87d5-bfea214fa2ad'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La paillasse de Louis avant le TP","competence":"observer-schema","situation":"Louis arrive en TP. Sa voisine remarque que sa paillasse n’est pas prête : certains objets n’ont rien à y faire. Avant de commencer, il doit aussi se laver les mains.","documents":[{"id":"paillasse","type":"schema","titre":"Vue de dessus de la paillasse","largeur":320,"hauteur":200,"elements":[{"forme":"rect","x":20,"y":30,"l":280,"h":140,"arrondi":8,"teinte":"gris","motif":"clair"},{"forme":"emoji","x":70,"y":100,"emoji":"🎒","taille":40,"id":"z1","zone":true},{"forme":"emoji","x":150,"y":100,"emoji":"☕","taille":40,"id":"z2","zone":true},{"forme":"emoji","x":230,"y":100,"emoji":"🧪","taille":40,"id":"z3","zone":true},{"forme":"texte","x":160,"y":190,"texte":"Paillasse de Louis","taille":"petit","italique":true,"ancre":"milieu"}]}],"questions":[{"enonce":"Touche les deux objets qui n’ont rien à faire sur la paillasse.","aide":"Au laboratoire, on ne boit pas, on ne mange pas, et les sacs sont rangés ailleurs.","type":"zone","document":"paillasse","multiple":true},{"enonce":"Classe chaque équipement : protection collective (EPC) ou individuelle (EPI) ?","aide":"Une EPC protège tout le laboratoire ; un EPI protège seulement celui qui le porte.","type":"categories","categories":[{"id":"c0","texte":"EPC"},{"id":"c1","texte":"EPI"}],"items":[{"id":"i0","texte":"Poste de sécurité microbiologique"},{"id":"i1","texte":"Blouse en coton fermée"},{"id":"i2","texte":"Gants adaptés"},{"id":"i3","texte":"Lunettes de protection"},{"id":"i4","texte":"Hotte chimique"},{"id":"i5","texte":"Rince-œil"}]},{"enonce":"Remets dans l’ordre les étapes du lavage des mains.","aide":"On mouille avant de savonner et on termine par le séchage.","type":"ordre","items":[{"id":"a","texte":"Mouiller les mains"},{"id":"b","texte":"Rincer abondamment"},{"id":"c","texte":"Sécher avec un essuie-mains à usage unique"},{"id":"d","texte":"Savonner au moins 30 secondes"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"Le **sac** et le **gobelet de café** sont à ranger : la paillasse reste dégagée, et on ne boit ni ne mange au laboratoire."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1","i4":"c0","i5":"c0"}},"explication":"Hotte, poste de sécurité et rince-œil protègent **tout le laboratoire** (EPC). Blouse, lunettes et gants protègent **la personne qui les porte** (EPI)."},{"cle":{"type":"ordre","ids":["a","d","b","c"]},"explication":"On **mouille**, on **savonne** 30 secondes en insistant sur les ongles et les pouces, on **rince**, puis on **sèche** avec un essuie-mains à usage unique."}]$ex$::jsonb),
  ('fe03ae69-9ff2-5a5c-87d5-bfea214fa2ad'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Où jeter les déchets du TP de Jade ?","competence":"analyser-document","situation":"Jade termine son TP d’ensemencement. Sur sa paillasse restent des déchets de natures très différentes : chacun a son conteneur, et la paillasse doit être désinfectée proprement.","documents":[{"id":"dechets","type":"tableau","titre":"Les déchets du TP de Jade","colonnes":["Déchet","Nature"],"lignes":[["Boîte de Petri avec colonies","culture bactérienne"],["Cône de micropipette utilisé","plastique souillé"],["Lame de verre cassée","verre souillé par une culture"],["Éthanol usagé","solvant"],["Essuie-mains neuf","papier propre"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le déchet qui doit aller dans un collecteur rigide (objet coupant souillé).","aide":"Cherche l’objet qui peut couper ou piquer.","type":"zone","document":"dechets","multiple":false},{"enonce":"Range chaque déchet dans son conteneur.","aide":"Culture : DASRI. Coupant : collecteur rigide. Solvant : jamais à l’évier. Papier propre : ménager.","type":"categories","categories":[{"id":"c0","texte":"Sac DASRI"},{"id":"c1","texte":"Collecteur rigide DASRI"},{"id":"c2","texte":"Bidon de déchets chimiques"},{"id":"c3","texte":"Déchets ménagers"}],"items":[{"id":"i0","texte":"Lame de verre cassée"},{"id":"i1","texte":"Essuie-mains neuf"},{"id":"i2","texte":"Éthanol usagé"},{"id":"i3","texte":"Cône de micropipette utilisé"},{"id":"i4","texte":"Boîte de Petri avec colonies"}]},{"enonce":"Jade pulvérise le désinfectant puis essuie aussitôt la paillasse. Que peut-on dire ?","aide":"Un désinfectant a besoin de temps sur la surface.","type":"choix","options":[{"id":"a","texte":"Le désinfectant agit mieux quand on le retire très vite"},{"id":"b","texte":"La paillasse est parfaitement stérile grâce à l’essuyage immédiat"},{"id":"c","texte":"Le désinfectant n’a pas agi : il faut respecter son temps de contact"},{"id":"d","texte":"Une désinfection n’est utile qu’après la manipulation"}],"multiple":false},{"enonce":"Complète la règle de désinfection de la paillasse.","aide":"Une fois pour protéger l’échantillon, une fois pour protéger les suivants.","type":"trous","segments":["On désinfecte la paillasse ",0," la manipulation pour protéger le produit, et ",1," pour protéger les personnes suivantes."],"banque":["jamais","pendant","avant","après"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"La **lame de verre cassée**, souillée par une culture, va dans un collecteur rigide DASRI : elle peut blesser et infecter."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c3","i2":"c2","i3":"c0","i4":"c0"}},"explication":"Cultures et cônes souillés vont en **sac DASRI**, le verre souillé en **collecteur rigide**, le solvant dans un **bidon chimique** (jamais à l’évier), le papier propre en **déchets ménagers**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un désinfectant n’agit que s’il reste **assez longtemps** au contact de la surface : l’essuyer aussitôt annule son action. Et la désinfection ne **stérilise** pas la paillasse."},{"cle":{"type":"trous","trous":[["avant"],["apres"]]},"affichage":"avant · après","explication":"On désinfecte **avant** (protéger le produit d’une contamination) et **après** (protéger les suivants)."}]$ex$::jsonb),
  ('fe03ae69-9ff2-5a5c-87d5-bfea214fa2ad'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quel équipement pour quelle situation ?","competence":"raisonner","situation":"Le professeur de biotechnologies présente le plan du laboratoire et quatre situations d’urgence ou de risque. Les élèves doivent désigner, pour chaque situation, l’équipement collectif à utiliser.","documents":[{"id":"situations","type":"tableau","titre":"Quatre situations","colonnes":["N°","Situation"],"lignes":[["S1","Préparer une solution avec des vapeurs toxiques"],["S2","Ouvrir une culture à risque d’aérosols"],["S3","Une projection de soude atteint l’œil"],["S4","Le vêtement d’un élève est inondé d’acide"]],"enteteLignes":true,"source":"Situations écrites pour l’exercice"},{"id":"plan","type":"schema","titre":"Plan du laboratoire","largeur":320,"hauteur":190,"elements":[{"forme":"rect","x":20,"y":20,"l":280,"h":150,"arrondi":6,"teinte":"gris","motif":"clair"},{"forme":"rect","x":30,"y":30,"l":80,"h":40,"arrondi":4,"teinte":"bleu","motif":"clair","id":"z1","zone":true,"texte":"Hotte"},{"forme":"rect","x":120,"y":30,"l":80,"h":40,"arrondi":4,"teinte":"vert","motif":"clair","id":"z2","zone":true,"texte":"PSM"},{"forme":"rect","x":210,"y":30,"l":80,"h":40,"arrondi":4,"teinte":"jaune","motif":"clair","id":"z3","zone":true,"texte":"Rince-œil"},{"forme":"rect","x":210,"y":120,"l":80,"h":40,"arrondi":4,"teinte":"corail","motif":"clair","id":"z4","zone":true,"texte":"Douche"},{"forme":"texte","x":90,"y":135,"texte":"Paillasses","taille":"normal","italique":true,"ancre":"milieu"}]}],"questions":[{"enonce":"Pour la situation S4, touche l’équipement à utiliser.","aide":"Une large surface du corps est atteinte, pas seulement l’œil.","type":"zone","document":"plan","multiple":false},{"enonce":"Relie chaque situation à l’équipement collectif adapté.","aide":"La hotte évacue les vapeurs, le poste aspire et filtre l’air, le rince-œil et la douche rincent.","type":"association","gauche":[{"id":"g0","texte":"S1 : vapeurs toxiques"},{"id":"g1","texte":"S2 : aérosols de culture"},{"id":"g2","texte":"S3 : projection dans l’œil"},{"id":"g3","texte":"S4 : vêtement inondé"}],"droite":[{"id":"d0","texte":"Poste de sécurité microbiologique"},{"id":"d1","texte":"Rince-œil"},{"id":"d2","texte":"Douche de sécurité"},{"id":"d3","texte":"Hotte chimique"}]},{"enonce":"Pour S1, pourquoi la hotte vaut-elle mieux que de simples lunettes et des gants ?","aide":"Dans la prévention, quel type de protection privilégie-t-on d’abord ?","type":"choix","options":[{"id":"a","texte":"La hotte désinfecte les vapeurs et les rend sans danger pour tous"},{"id":"b","texte":"C’est une protection collective : elle évacue les vapeurs pour tout le laboratoire"},{"id":"c","texte":"La hotte rend inutile toute blouse et toute précaution personnelle"},{"id":"d","texte":"Les gants et les lunettes sont interdits dès qu’on utilise un produit chimique"}],"multiple":false},{"enonce":"Pour S3, touche l’équipement à utiliser en premier.","aide":"Seul l’œil est touché.","type":"zone","document":"plan","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"Un vêtement inondé d’acide impose la **douche de sécurité** : on rince abondamment toute la surface atteinte."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"La **hotte** évacue les vapeurs toxiques, le **poste de sécurité** aspire et filtre l’air des aérosols, le **rince-œil** traite l’œil et la **douche** le corps."},{"cle":{"type":"choix","ids":["b"]},"explication":"On privilégie d’abord la **protection collective** : la hotte évacue les vapeurs pour tous. La protection individuelle vient **en complément**, pas à sa place."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Pour une projection dans l’œil, on utilise le **rince-œil** sans attendre, pendant plusieurs minutes."}]$ex$::jsonb),
  ('7e106d46-15aa-59e2-b205-794287e83d93'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La fiche de TP de Camille : dosage du glucose","competence":"lire-tableau","situation":"Camille dose le glucose d’un sérum au spectrophotomètre. Elle range ses notes sur une fiche de TP et prépare aussi une solution étalon dans une fiole jaugée.","documents":[{"id":"fiche","type":"fiche","modele":"etiquette","titre":"Fiche de TP","entete":"Dosage du glucose du sérum","sousTitre":"Notes de Camille","emoji":"🧪","lignes":[{"texte":"Mesurande","valeur":"concentration en glucose du sérum","id":"z1"},{"texte":"Indication du spectrophotomètre","valeur":"0,452","id":"z2"},{"texte":"Valeur mesurée","valeur":"5,2 mmol·L⁻¹","id":"z3"},{"separateur":true},{"texte":"Étalon : 0,45 g de glucose dans une fiole jaugée de 50,0 mL","id":"z4"}],"pied":"Fiche écrite pour l’exercice","teinte":"violet"}],"questions":[{"enonce":"Touche la ligne qui donne l’indication de l’instrument, c’est-à-dire ce qu’il affiche.","aide":"L’indication est un nombre brut, sans conversion en concentration.","type":"zone","document":"fiche","multiple":false},{"enonce":"Quelle est la concentration en masse de la solution étalon, en g·L⁻¹ ? (0,45 g dans 50,0 mL)","aide":"Convertis d’abord 50,0 mL en litres, puis divise la masse par le volume.","type":"nombre","unite":"g·L⁻¹"},{"enonce":"Relie chaque grandeur à son unité du Système international ou usuelle.","aide":"Les trois premières sont des grandeurs de base ; la dernière est dérivée (masse divisée par volume).","type":"association","gauche":[{"id":"g0","texte":"Masse"},{"id":"g1","texte":"Temps"},{"id":"g2","texte":"Quantité de matière"},{"id":"g3","texte":"Concentration en masse"}],"droite":[{"id":"d0","texte":"mol"},{"id":"d1","texte":"s"},{"id":"d2","texte":"g·L⁻¹"},{"id":"d3","texte":"kg"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"L’**indication** du spectrophotomètre est **0,452** : c’est ce qu’il affiche. La valeur mesurée (5,2 mmol·L⁻¹) vient d’un calcul."},{"cle":{"type":"nombre","valeur":9,"tolerance":0.01},"affichage":"9 g·L⁻¹","explication":"50,0 mL = 0,0500 L, donc ρ = m / V = 0,45 / 0,0500 = **9,0 g·L⁻¹**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"Masse (**kg**), temps (**s**) et quantité de matière (**mol**) sont des grandeurs de base ; la concentration en masse m / V s’exprime en **g·L⁻¹**."}]$ex$::jsonb),
  ('7e106d46-15aa-59e2-b205-794287e83d93'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quelle verrerie pour prélever 10 mL de sérum ?","competence":"analyser-document","situation":"Le technicien du laboratoire doit prélever 10 mL de sérum, préparer 100 mL d’une solution et rincer des flacons. Il dispose de la verrerie du tableau et doit choisir selon l’exactitude demandée.","documents":[{"id":"verrerie","type":"tableau","titre":"Verrerie disponible","colonnes":["Verrerie","Volume","Tolérance"],"lignes":[["Pipette jaugée, classe A","10 mL","± 0,02 mL"],["Pipette graduée","10 mL","± 0,05 mL"],["Éprouvette graduée","10 mL","± 0,2 mL"],["Bécher","50 mL","indicatif"]],"enteteLignes":true,"source":"Tolérances données à titre d’exemple pour l’exercice"}],"questions":[{"enonce":"Touche la verrerie la plus exacte pour prélever 10 mL.","aide":"La plus exacte est celle dont la tolérance est la plus petite.","type":"zone","document":"verrerie","multiple":false},{"enonce":"Combien de fois l’éprouvette graduée est-elle moins exacte que la pipette jaugée ? (rapport des tolérances)","aide":"Divise la tolérance de l’éprouvette par celle de la pipette jaugée.","type":"nombre"},{"enonce":"Range chaque verrerie : contient (« in »), délivre (« ex ») ou indicative ?","aide":"« in » : elle contient son volume. « ex » : elle le délivre. Bécher et erlenmeyer : jamais pour mesurer.","type":"categories","categories":[{"id":"c0","texte":"Verrerie « in »"},{"id":"c1","texte":"Verrerie « ex »"},{"id":"c2","texte":"Verrerie indicative"}],"items":[{"id":"i0","texte":"Erlenmeyer"},{"id":"i1","texte":"Pipette graduée"},{"id":"i2","texte":"Fiole jaugée"},{"id":"i3","texte":"Bécher"},{"id":"i4","texte":"Pipette jaugée"}]},{"enonce":"Pour préparer exactement 100 mL d’une solution étalon, quelle verrerie choisit-on ?","aide":"Pour préparer une solution, on veut un volume contenu exactement.","type":"choix","options":[{"id":"a","texte":"Une pipette graduée de 10 mL"},{"id":"b","texte":"Un bécher de 100 mL gradué"},{"id":"c","texte":"Une éprouvette graduée de 100 mL"},{"id":"d","texte":"Une fiole jaugée de 100 mL"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0"]},"explication":"La **pipette jaugée** a la tolérance la plus faible (± 0,02 mL) : c’est elle qu’on choisit pour un volume précis."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10","explication":"0,2 / 0,02 = **10** : l’erreur possible avec l’éprouvette est dix fois plus grande."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0","i3":"c2","i4":"c1"}},"explication":"La **fiole jaugée** contient son volume (« in ») ; les **pipettes** le délivrent (« ex ») ; le **bécher** et l’**erlenmeyer** ont des graduations seulement indicatives."},{"cle":{"type":"choix","ids":["d"]},"explication":"La **fiole jaugée** est étalonnée « in » : elle contient exactement son volume, c’est la verrerie de préparation d’une solution."}]$ex$::jsonb),
  ('7e106d46-15aa-59e2-b205-794287e83d93'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quatre relevés de glucose : sont-ils comparables ?","competence":"raisonner","situation":"Quatre élèves ont relevé le glucose dans des échantillons. Leur professeur veut savoir quels résultats se comparent directement, puis vérifier la masse volumique du sérum à partir d’une pesée.","documents":[{"id":"releves","type":"tableau","titre":"Résultats des quatre élèves","colonnes":["Élève","Grandeur","Valeur"],"lignes":[["Théo","ρ(glucose, sérum)","0,95 g·L⁻¹"],["Inès","ρ(glucose, urine)","0,02 g·L⁻¹"],["Sam","ρ(glucose, sérum)","0,91 g·L⁻¹"],["Lina","C(glucose, sérum)","5,2 mmol·L⁻¹"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"},{"id":"pesee","type":"fiche","modele":"etiquette","titre":"Pesée de Théo","entete":"Masse volumique du sérum","sousTitre":"Prélèvement à la pipette jaugée","emoji":"⚖️","lignes":[{"texte":"Volume prélevé","valeur":"5,00 mL"},{"texte":"Tolérance de la pipette","valeur":"± 0,015 mL"},{"texte":"Masse pesée","valeur":"5,15 g"}],"pied":"Fiche écrite pour l’exercice","teinte":"bleu"}],"questions":[{"enonce":"Touche les deux grandeurs directement comparables (même entité, même matrice, même unité).","aide":"Repère les indices entre parenthèses : ils donnent l’entité puis la matrice.","type":"zone","document":"releves","multiple":true},{"enonce":"Convertis la valeur de Lina en g·L⁻¹ (M(glucose) = 180 g·mol⁻¹), arrondie au centième.","aide":"Multiplie la concentration en quantité de matière par la masse molaire.","type":"nombre","unite":"g·L⁻¹"},{"enonce":"Quelle condition rend deux valeurs de concentration comparables ?","aide":"Les indices servent à préciser quoi, et dans quoi.","type":"choix","options":[{"id":"a","texte":"Même élève et même jour de mesure"},{"id":"b","texte":"Même entité, même matrice et même unité"},{"id":"c","texte":"Même instrument et même nombre de chiffres"},{"id":"d","texte":"Même grandeur et même ordre de grandeur"}],"multiple":false},{"enonce":"Quelle est la masse volumique du sérum d’après la pesée de Théo, en g·mL⁻¹ ?","aide":"Masse volumique = masse divisée par volume.","type":"nombre","unite":"g·mL⁻¹"},{"enonce":"Compte tenu de la tolérance de la pipette, quel volume maximal a pu être réellement prélevé ?","aide":"Ajoute la tolérance au volume nominal.","type":"nombre","unite":"mL"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r2c1"]},"explication":"ρ(glucose, sérum) pour Théo et pour Sam : même entité, **même matrice**, même unité. Inès a mesuré une autre matrice (urine) ; Lina utilise une autre grandeur."},{"cle":{"type":"nombre","valeur":0.94,"tolerance":0.005},"affichage":"0,94 g·L⁻¹","explication":"ρ = C × M = 5,2 × 10⁻³ mol·L⁻¹ × 180 g·mol⁻¹ = 0,936, soit **0,94 g·L⁻¹** : cette valeur devient comparable à celles de Théo et de Sam."},{"cle":{"type":"choix","ids":["b"]},"explication":"Deux valeurs sont comparables si elles portent sur la **même entité**, dans la **même matrice**, exprimées dans la **même unité**."},{"cle":{"type":"nombre","valeur":1.03,"tolerance":0.005},"affichage":"1,03 g·mL⁻¹","explication":"ρ = m / V = 5,15 g / 5,00 mL = **1,03 g·mL⁻¹**."},{"cle":{"type":"nombre","valeur":5.015,"tolerance":0.0005},"affichage":"5,015 mL","explication":"5,00 + 0,015 = **5,015 mL** : le volume réel est compris entre 4,985 et 5,015 mL."}]$ex$::jsonb),
  ('4014bdbc-478c-51e8-ab37-3e66ace6c938'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un étalon, un essai, une concentration","competence":"calculer","situation":"Noé dose le glucose d’un échantillon avec un étalon unique. Le spectrophotomètre a donné les absorbances du tableau et il doit en déduire la concentration de l’essai.","documents":[{"id":"mesures","type":"tableau","titre":"Mesures de Noé","colonnes":["Solution","C (mmol·L⁻¹)","Absorbance A"],"lignes":[["Étalon","4,0","0,320"],["Essai","?","0,240"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche l’absorbance de l’essai.","aide":"L’essai est la ligne dont la concentration est inconnue.","type":"zone","document":"mesures","multiple":false},{"enonce":"Remets dans l’ordre les trois équations du modèle de mesure.","aide":"On écrit la formule, on vérifie les unités, puis on remplace par les nombres.","type":"ordre","items":[{"id":"a","texte":"Équation aux valeurs numériques"},{"id":"b","texte":"Équation aux grandeurs"},{"id":"c","texte":"Équation aux unités"}]},{"enonce":"Calcule la concentration de l’essai avec C(essai) = C(étalon) × A(essai) / A(étalon).","aide":"Multiplie 4,0 par 0,240 puis divise par 0,320.","type":"nombre","unite":"mmol·L⁻¹"}]}$ex$::jsonb,
